D.SpellTexts[202815]={Description={["cd441a52c82abd47:367"]="很多人都认为这位臭名昭著的迪菲亚兄弟会头目几年前已经在死亡矿井中丧生。然而，凭借一瓶能让人暂时装死的药剂和一套防火护甲，西部荒野的任性女儿得以逃出生天。此后她加入了一个名为“无冕者”的秘密组织，对政府的强烈叛逆让她在里面如鱼得水。她在组织中的地位迅速提升，成为了一名神秘的“影行者”，坚定地向着自己的复仇大业前进。"}}
