D.SpellTexts[203633]={Description={["d0ffa935ca8011ce:410"]="多年以来，塞丝诺女士和库斯卡纳迦一直在与伊利达雷并肩作战。塞斯诺过人的魔法能力很快得到了高阶督军纳因图斯的赏识。高阶督军在围攻黑暗神殿的战斗中战死，在库斯卡纳迦的军队中留下了权力真空。塞丝诺女士做了每一名仍然保留有自尊心的纳迦海妖都会做的事。她指挥着所有仍然忠于伊利达雷的库斯卡纳迦，让那些胆敢挑衅她的人感受到了死亡的威胁。"}}
