D.SpellTexts[205408]={Description={["f3777cffb4c8e33e:227"]="用星座标记玩家。被标记为相同星座的玩家相互接触时将清除他们的星座标记。被标记为不同星座的玩家相互接触，则会触发星象三角效果。\r\n\r\n如果星座标记在持续时间内没有被移除，同样会触发星象三角效果。"}}
