D.SpellTexts[206560]={Description={["2bf6365d317e29b2:72"]="崔利艾克斯被清洁者人格占据，想要将整个团队从这个世界上清除。"},Aura={["3a10f7f20825f835:12"]="清洁者模式。"}}
