D.SpellTexts[206567]={Description={["730db2ccc3403e79:92"]="施法者从目标身上窃取艾露恩之光。击败这个生物后艾露恩之光会掉落在附近。"},Aura={["0040419cc2ec28f3:54"]="这个生物携带着窃取的艾露恩之光。"}}
