D.SpellTexts[206935]={Aura={["e3d8e436d1a25849:52"]="对你造成近战伤害的敌人将感染血之疫病。"}}
D.SpellTexts[206946]={Description={["b6651904aef9995d:46"]="召唤8个血肉之子协助施法者。"}}
D.SpellTexts[206950]={Description={["faa3ede50af4dbe2:56"]="施放一个圣言术法术将会对你其他的圣言术法术触发妙手回春。"}}
D.SpellTexts[206955]={Description={["500a23cfd7a34932:67"]="向目标地点吐出一条河豚鱼。3秒钟后，河豚鱼会爆炸。"}}
