D.SpellTexts[206983]={Description={["53252ea67e8c7731:74"]="从扭曲虚空中凝视一个目标，使目标昏迷并追逐它。"},Aura={["13134acc5e54df07:44"]="昏迷。\r\n一只寄生暗影恶魔向你冲过来了！"}}
D.SpellTexts[206996]={Description={["6d5846ef0e9943aa:58"]="潮汐喷薄而出，对附近的敌人造成自然伤害，并将其击飞。"}}
D.SpellTexts[207012]={Aura={["1cd592e1786853a0:22"]="时间以正常速度流逝。"}}
D.SpellTexts[207014]={Description={["0177d147dc2f7934:32"]="根据受到的伤害产生痛苦值。"}}
