D.SpellTexts[207051]={Description={["f32c5f05607b54ac:158"]="吸收相当于施放时受害者最大生命值的治疗量。效果结束时，受害者受到奥术伤害，其数值相当于剩余的治疗吸收量。"}}
D.SpellTexts[207059]={Description={["8bc24a76ec126fcf:78"]="向目标发射一枚巨大的鱼叉，造成大量的物理伤害，并忽略护甲。"}}
D.SpellTexts[207066]={Description={["f02322b9de277d4c:51"]="从怒火余烬或神圣能量裂隙中吸收能量。"},Aura={["5bead2ac6ac52b09:52"]="从怒火余烬或神圣能量裂隙中吸收能量。"}}
D.SpellTexts[207068]={Rank={["5e500f93cabfbb92:8"]="神器"}}
D.SpellTexts[207074]={Aura={["af42b70680ea14b3:7"]="昏迷"}}
D.SpellTexts[207115]={Description={["05b1a3688e674f3b:34"]="拾起一捆编织绷带。"},Aura={["1ce6effba707c726:36"]="携带着一捆编织绷带。"}}
D.SpellTexts[207116]={Description={["ef9c5fffdc6fa8ca:150"]="扎卡兹在现实中撕出孔洞，对站在其中的所有敌人造成暗影伤害。\r\n\r\n此外孔洞中还会周期性地涌出血肉之子，攻击附近所有玩家。"}}
D.SpellTexts[207117]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
