D.SpellTexts[207137]={Aura={["94e4d5931a9b0fac:24"]="被奥术魔法禁锢。"}}
D.SpellTexts[207144]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[207145]={Description={["827b521e7fdb2383:54"]="虚空能量从玩家身上爆发出来，并召唤出数只虚空之子。"}}
D.SpellTexts[207149]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[207165]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[207167]={Aura={["3902644d115b38bc:12"]="迷惑。"}}
D.SpellTexts[207168]={Aura={["6a0ae65d4b55f808:31"]="被神秘的力量吸引……"}}
D.SpellTexts[207169]={Description={["72027954b3377d93:41"]="在施法者身边召唤一对镜像。"}}
D.SpellTexts[207171]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[207175]={Description={["7861e8042b2972a9:78"]="扎卡兹撕裂前方锥形范围内所有目标的神智，对其造成暗影伤害。"}}
D.SpellTexts[207215]={Aura={["6e86e8c7cfad4d08:17"]="净化加尼尔。"}}
D.SpellTexts[207217]={Description={["88f1a18f5de7105e:114"]="祝踏岚带领着影踪派努力保护潘达利亚不受煞的侵害，他是一名技艺非凡的勇士，也是一位无畏的领袖。"},Aura={["fa68637c43931b1d:45"]="祝踏岚是速度、敏捷与力量的大师。"}}
D.SpellTexts[207219]={Description={["16cd0ce82c5445b5:131"]="美猴王是潘达利亚的皇帝少昊最信赖的勇士。他的性格精灵古怪，并了解许多关于潘达利亚历史的不传之秘。"},Aura={["52ae0c10cf44bb6d:77"]="美猴王在战斗中花招百出，难于预测。他那疯狂而古怪的动作总是能够克敌制胜。"}}
D.SpellTexts[207220]={Description={["4c8f72a2c3c54e55:181"]="安古斯·铁拳是天生的战士，热衷于和任何对手单挑。他将武术、擒拿、摔跤等技术结合在了一起，出拳踢脚的时机精准老辣，在战斗中无往不利。"},Aura={["19ef71f76318caa6:54"]="安古斯·铁拳面对战斗从不退缩，更不会放弃！"}}
D.SpellTexts[207222]={Description={["9d0f86394749d626:205"]="希罗在这个世界上游荡了许多年，漫不经心地从一间酒馆走向下一间，到处找酒喝。不过不要被他那不修边幅的外表骗到了，他不仅有一颗金子般的心，更重要的是，喝的酒越多，他在战斗中的表现也就越好。"},Aura={["40f545fa19925f47:49"]="准备好战斗了吗？朝他扔一桶酒，或者十桶，看看会发生什么事吧。"}}
D.SpellTexts[207223]={Description={["e7f008aca90ff7bd:166"]="赛莱拉·影心是一个神秘的流浪者，她很少谈及自己的过去。大家只知道她有着嫉恶如仇的性格。任何违逆她意志的人都会尝到她手中双刀的滋味。"},Aura={["66d65b3c8d04dea5:56"]="赛莱拉·影心是一个永不休息的流浪者，有着神秘的过去。"}}
D.SpellTexts[207225]={Description={["56d9177ae31b4f73:185"]="艾吉拉是一名维库酿酒大师，受到了奥丁本人的眷顾。她能酿造传奇美酒，但很少有人知道，她还有着极为强大的战斗力。她在战场上长大，至今都没有输给过任何挑战者。"},Aura={["94a7deef6805e412:66"]="艾吉拉是传奇般的维库酿酒大师，她的战斗技巧也不容小视。"}}
D.SpellTexts[207229]={Description={["2686a05fd8bdbcfc:58"]="对施法者前方锥形范围内的所有目标造成暗影伤害。"}}
D.SpellTexts[207235]={Description={["ac436d956a17a74c:168"]="赛莱托斯大使是天空之墙中最古老、最受尊敬的元素生物。\r\n\r\n在奥拉基尔的统治期间，赛莱托斯是他的首席顾问及军事参谋，参与了风元素领主的多次战役。"},Aura={["69922beff5417b42:50"]="赛莱托斯大使能在战斗中掌控狂风与天空的怒火。"}}
D.SpellTexts[207236]={Description={["c745800b840ee19e:178"]="作为曾经的圣骑士，预言者努波顿是他的人民中第一个学习元素之道并成为萨满祭司的人。\r\n\r\n他是大地之环中最睿智、最强大的萨满祭司之一，也是这个组织曾经的领袖。"},Aura={["ead53faddb6738fc:106"]="预言者努波顿精通所有的萨满教义，可以在战斗中治疗和保护盟友。"}}
D.SpellTexts[207237]={Aura={["d688542281bcd555:64"]="雷加尔·大地之怒驱使元素之力打败敌人。"}}
D.SpellTexts[207238]={Aura={["61448fc25a831ea1:65"]="斯卡迪乌斯男爵会极其残暴、一往无前地打击敌人。"}}
D.SpellTexts[207239]={Aura={["8785ee70af32b7c3:79"]="阿瓦兰奇奥是一位强大的石领主，可以在战斗中保护盟友，吸引敌人的攻击。"}}
D.SpellTexts[207240]={Aura={["1b6c660c0526ee35:104"]="穆恩·大地之怒用元素之力强化他的攻击，让他在战场上获得速度与力量。"}}
D.SpellTexts[207244]={Description={["e870a015bfe4628a:52"]="施法者分裂成三个阴暗的无面者碎片。"}}
D.SpellTexts[207256]={Aura={["1bc2037d7e5a1b60:68"]="湮灭的消耗降低。冰霜打击和凛风冲击可以赋予杀戮机器效果。"}}
D.SpellTexts[207281]={Description={["6c0f47a76b595242:14"]="正在操作"}}
D.SpellTexts[207293]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[207294]={Description={["0d2e4feb0aa45010:63"]="对选定区域内的所有敌人造成火焰伤害并将其击退。"}}
D.SpellTexts[207300]={Aura={["cc0dd0267a1292bd:31"]="提高攻击和施法速度。"}}
D.SpellTexts[207313]={Description={["8bbfbf7b5069be88:76"]="亡者复生现在召唤一个憎恶而非食尸鬼，拥有更强大的初始技能。"}}
D.SpellTexts[207327]={Aura={["e9bc35ae49dbf095:15"]="快要爆炸了！"}}
D.SpellTexts[207344]={Description={["bb04a23f5b7120e6:66"]="向目标射出一团暗影魔法，窃取一个生命精华碎片。"}}
D.SpellTexts[207345]={Description={["c4178c197bd24bd8:53"]="从其他人身上偷取的生命精华强化施法者的法术。"}}
D.SpellTexts[207404]={Description={["ad21a820897787ef:55"]="魅惑目标枯法者，使其在苏拉玛协助你战斗。"},Aura={["096219e7b8e2e098:8"]="魅惑。"}}
D.SpellTexts[207407]={Rank={["5e500f93cabfbb92:8"]="神器"}}
D.SpellTexts[207409]={Description={["d9ed6a196a67ee20:55"]="目标被魅惑，变成一只疯狂生物。"}}
