D.SpellTexts[207413]={Description={["b12c30e41d6aad4f:20"]="带领着一只冬日麋鹿。"},Aura={["b12c30e41d6aad4f:20"]="带领着一只冬日麋鹿。"}}
D.SpellTexts[207447]={Description={["1d2b29ebfbea546e:56"]="变形进入熊形态，获得额外的护甲值与新的技能。"},Aura={["89be3f884a2ba0dd:28"]="变形。\r\n护甲值提高。"},Rank={["7f5c1454467b72e1:10"]="变形"}}
D.SpellTexts[207451]={Description={["56ed4c6365d975f0:20"]="点燃什么东西。"}}
D.SpellTexts[207457]={Description={["6131cf9620674a4d:59"]="通过灵魂之旅回到过去，寻找抵御上古之神的结界。"},Aura={["6131cf9620674a4d:59"]="通过灵魂之旅回到过去，寻找抵御上古之神的结界。"}}
D.SpellTexts[207458]={Aura={["9fdbe41063141823:7"]="诱捕。"}}
D.SpellTexts[207460]={Description={["d00ddd9cfb2333c5:54"]="召唤一个灌注梦魇之力的种子，有人踩到时会发生爆炸。"}}
D.SpellTexts[207488]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[207499]={Description={["2cb0b7ea59f3ff41:56"]="对潮汐主母和她的鳞卫造成大量伤害。"}}
D.SpellTexts[207513]={Description={["636fe0e13a698fd8:46"]="召唤清扫器，清理奥术渗流留下的池子。"}}
