D.SpellTexts[207567]={Description={["defe60e7d7b8457e:66"]="施法者充满了能量，其施法不会被打断。"},Aura={["18279cd7b79ad12a:16"]="不会被打断。"}}
D.SpellTexts[207576]={Description={["84b3ecc0fed7f24d:45"]="在区域内时每秒造成火焰伤害。"},Aura={["cd3ac87aa01faa6f:27"]="每秒造成一次火焰伤害。"}}
