D.SpellTexts[207586]={Description={["45b932b5a46ef752:85"]="阅读可以让你获得关于神器的新知识，提高获得神器能量的速度。"}}
D.SpellTexts[207588]={Description={["fa32ca1a6eb17bfb:44"]="减缓一个特别的厄运诅咒的作用过程。"}}
D.SpellTexts[207592]={Description={["fbfddc65d0590814:52"]="向敌人投掷一个腐烂的南瓜，造成自然伤害。"}}
D.SpellTexts[207596]={Description={["1369e9e6b239a1c5:21"]="制造一个妖术神像。"}}
D.SpellTexts[207600]={Description={["eac252e6ef5b9f8d:42"]="朝眼中望去，强化你的神器。"}}
D.SpellTexts[207629]={Description={["79b52b414b3ae7cc:54"]="跳到周围的一个位置，潜入阴影，准备攻击！"},Aura={["1c37242c06cbf171:68"]="潜行。\r\n潜行状态下发动的第一次攻击造成300%额外伤害。"}}
D.SpellTexts[207647]={Description={["3830fe287dcd771b:23"]="攻击会治疗攻击者。"},Aura={["3830fe287dcd771b:23"]="攻击会治疗攻击者。"}}
D.SpellTexts[207662]={Description={["229a79d82c60ea7f:53"]="用利爪撕扯目标，使其感染梦魇之种。"},Aura={["d3a39def6b8f5fec:51"]="梦魇腐蚀每秒会造成暗影伤害。"}}
D.SpellTexts[207663]={Description={["2c02b85d7c20db02:57"]="发出刺耳尖啸，对周围的所有敌人造成物理伤害。"}}
D.SpellTexts[207664]={Description={["9d33850965d3a226:52"]="心灵震爆会刷新暗言术：痛的持续时间。"}}
D.SpellTexts[207672]={Description={["5f73944925cfc5f4:30"]="附近有一个强大的自然之灵。"},Aura={["5f73944925cfc5f4:30"]="附近有一个强大的自然之灵。"}}
D.SpellTexts[207685]={Aura={["3902644d115b38bc:12"]="迷惑。"}}
D.SpellTexts[207686]={Aura={["acd7037ab623bd07:26"]="被定身。\r\n受到自然伤害。"}}
D.SpellTexts[207687]={Description={["32171419efafa9ae:52"]="召唤一个缠藤图腾，将20码内的敌人定身。"}}
D.SpellTexts[207695]={Aura={["cf16ee169a75c0d3:38"]="你的鱼漂变成了一罐虫子。"}}
D.SpellTexts[207696]={Aura={["48ad1c9ddafe1e34:38"]="你的鱼漂变成了一只玩具猫头。"}}
D.SpellTexts[207698]={Aura={["0e8da2545aa716cf:38"]="你的鱼漂变成了一只鸭子。呱！"}}
