D.SpellTexts[211701]={Description={["d9c7bf09e86b71fa:59"]="从扭曲虚空召唤一个大恶魔为施法者战斗。"}}
D.SpellTexts[211707]={Description={["e3e3c50f14bd0fda:210"]="作为海达希亚水元素的领袖，海达克西斯公爵在熔火之心击败拉格纳罗斯的战役中发挥了极为重要的作用。现在他身为猎潮者耐普图隆的右手，在艾泽拉斯贯彻着这位潮汐领主的意志。"},Aura={["bc36428192d4def6:122"]="海达克西斯公爵是具有强大力量的水元素，能够将毁灭降临于敌人身上，也能用治愈水流来对盟友进行治疗。"}}
D.SpellTexts[211710]={Description={["ab842407fad492ee:176"]="风暴召唤者米尔拉是位经验丰富的增强萨满，也是一名忠于大地之环的勇士。\r\n\r\n和其他蛮锤氏族的成员一样，她与自己的狮鹫风暴比克的感情十分深厚，两者很少分开。"},Aura={["d1eb4fdc56607613:122"]="风暴召唤者米尔拉使用元素的力量强化自己的物理攻击。在蛮锤氏族中，几乎没有人能和她一较高下。"}}
D.SpellTexts[211714]={Rank={["5e500f93cabfbb92:8"]="神器"}}
D.SpellTexts[211723]={Description={["9db894b395c9bb24:62"]="集中你的力量，强行与扭曲虚空中的一个实体进行沟通。"},Aura={["9db894b395c9bb24:62"]="集中你的力量，强行与扭曲虚空中的一个实体进行沟通。"}}
D.SpellTexts[211740]={Aura={["be36677b7ccb2832:30"]="掌握着泰坦之击的力量。"}}
D.SpellTexts[211773]={Description={["06c1c518c24c4f75:21"]="造成奥术伤害。"}}
