D.SpellTexts[211898]={Description={["bf7c08a41150109f:96"]="召唤审判官之眼并通过它来观察世界。审判官之眼处于潜行状态，且移动迅速，但是非常脆弱。"},Aura={["54876db68f694075:49"]="控制审判官之眼。\r\n侦测隐形。"}}
