D.SpellTexts[211918]={Description={["c2b747937a861904:84"]="获得凤凰烈焰技能，向目标附近的所有敌人投出毁灭一切的火焰。"},Aura={["4374443cb696f247:29"]="献祭敌人的尸体。"}}
D.SpellTexts[211926]={Description={["97fb60114f1698c0:58"]="可以在破碎群岛中治疗受伤的冒险者。"}}
