D.SpellTexts[212437]={Description={["c2bb51cfc21d5e50:44"]="对一名敌人造成火焰伤害，并使其下马。"},Aura={["c2bb51cfc21d5e50:44"]="对一名敌人造成火焰伤害，并使其下马。"}}
