D.SpellTexts[212630]={Description={["cb85f4208325adff:243"]="玛法里奥会在梦魇大军所在的区域中选择玩家人数最多的一块加以净化。被净化的梦魇盟友会变为自然盟友。此外还会净化目标区域12码内的玩家身上所有的蠕行梦魇。"},Aura={["8a0c607b981cc688:49"]="净化一个梦魇盟友脚下的地面。"}}
