D.SpellTexts[215045]={Description={["825e2e710c2976b0:78"]="这个生物的弹性电路非常难以驯服，必须先将它超载。"},Aura={["beb7f67705fdcaf4:31"]="驯服前必须先用电流使其超载。"}}
D.SpellTexts[215084]={Description={["392917a915ab233c:21"]="快速向后跳跃。"}}
D.SpellTexts[215116]={Description={["ec9c1db87e212943:201"]="阿卡玛是伊利丹摧毁燃烧军团计划的主策划师，以及灰舌氏族的首领，他早已证明了自己是个足智多谋的领袖、极具智慧的战略家，同时也是技能娴熟的斗士。他的影子同样如此，并且更为强大。"},Aura={["989d67300eebe8bb:53"]="阿卡玛之影是潜行、战斗和战略大师。"}}
D.SpellTexts[215117]={Description={["c9c163e57b89772a:193"]="玛沃伦丝屡次用行为证明自己是名无价的盟友。很显然的事实就是，如果不是她，你根本就无法站在这里。她的领袖技巧和所精通的恶魔法术可谓相得益彰。"},Aura={["656908d91db17498:69"]="主母玛沃伦丝是邪能魔法和战术大师，极为擅长制造苦痛。"}}
D.SpellTexts[215127]={Aura={["63cd329288c796c3:13"]="正在呕吐。呃。"}}
D.SpellTexts[215129]={Description={["7df28b915baad1da:260"]="伊利丹不计代价地与燃烧军团战斗，没有人敢对他的方法提出质疑。但这时，奥图里斯站了出来。作为一名闻名已久的强大恶魔猎手，他的战斗能力毋庸置疑。比战斗技巧更重要的，是他敏锐的智慧和所受到的尊重。正是靠着这些，他推动了伊利达雷的改变。"},Aura={["bd9c03525a19e319:108"]="受难者奥图里斯已经掌握了浩劫恶魔猎手之道。他也因其领导能力和战略意识而受到尊重。"}}
D.SpellTexts[215133]={Description={["80843d6334d03cd6:248"]="在经历一切后，凯恩如同废墟中屹立不动的柱石。当其他人开始质疑伊利丹的方法时，凯恩依然坚定不移地认为，摧毁燃烧军团才是重中之重。他是一名强大的战士，精明的战略家，同时也是一位无与伦比的政治家。"},Aura={["61d952d105c61118:112"]="凯恩·日怒精通浩劫恶魔猎手之道。他因其领导能力和对伊利达雷坚定不移的信念而受到尊重。"}}
D.SpellTexts[215138]={Description={["a8e3c8cda3857df2:256"]="阿莎·鸦歌是伊利达雷最忠诚和专注的战士。她非常安静，思虑成熟，并且极为致命。当她采取行动时，所做的决策都极为准确。正因如此，她获得了周围所有人的尊重。很少有人能在和她的战斗中幸存，她的智谋更是无人能及。"},Aura={["921f8c19424fe15a:128"]="阿莎·鸦歌已经掌握了复仇恶魔猎手之道。她因其致命专注的能力，以及对大局的把控而受到尊重。"}}
D.SpellTexts[215142]={Description={["fb5f9fd73bb6e85c:51"]="引导烈风，将敌人向后推去。"},Aura={["fb5f9fd73bb6e85c:51"]="引导烈风，将敌人向后推去。"}}
D.SpellTexts[215148]={Description={["1148abdcbb721437:209"]="考瓦斯因其无与伦比的武器技巧而闻名于世。有人说，她对战刃的运用之纯熟，甚至和伊利丹相比都不落下风。她暴躁的性情和战斗中的残忍也是尽人皆知，在战斗中从不留活口。"},Aura={["5484c0c24e0d9439:81"]="考瓦斯·血棘已经掌握了浩劫恶魔猎手之道，她同时精通于所有类型的格斗技巧。"}}
D.SpellTexts[215159]={Description={["d2d2c476823f1e07:77"]="召唤或解散一匹可骑乘的失落已久的角鹰兽。这是飞行坐骑。"}}
D.SpellTexts[215169]={Description={["8050fbaa6d67ee67:97"]="鱼人的尸体会吸来一群钉刺昆虫，对区域内的任意玩家造成自然伤害。"},Aura={["cb728af1eaa11488:33"]="每秒受到一次自然伤害。"}}
D.SpellTexts[215193]={Description={["5e468bb92fce9846:27"]="激活或关闭宝石。"}}
D.SpellTexts[215195]={Description={["8315daf2995a43eb:80"]="施法者将矛沿直线投出。沿途的所有敌人都会受到奥术伤害。"}}
D.SpellTexts[215204]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[215207]={Description={["e49fb43197bee4b6:67"]="这个容器内应该充满了来自艾萨拉之怒的水。"}}
D.SpellTexts[215208]={Aura={["0f1b7e8d2c7f343a:26"]="受到冰霜伤害。\r\n昏迷。"}}
D.SpellTexts[215217]={Description={["99bbda996d7b8db6:72"]="施法者向前冲锋，对其行进路线上的所有敌人造成物理伤害。"}}
D.SpellTexts[215237]={Description={["9f8b69c38e8861b4:80"]="在敌人脚下形成一道急流，造成冰霜伤害并将其击飞到空中。"}}
D.SpellTexts[215238]={Aura={["7a6e87831823004e:10"]="收拾干净！"}}
D.SpellTexts[215258]={Aura={["6e86e8c7cfad4d08:17"]="净化加尼尔。"}}
D.SpellTexts[215259]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[215274]={Aura={["920f767c3a19035d:27"]="强化潜行侦测。"}}
D.SpellTexts[215275]={Description={["9cefd036179eb3cf:40"]="传送到潜岩者裂谷的入口"}}
D.SpellTexts[215276]={Description={["9ad3d88dee31b42c:17"]="召唤一个混乱裂隙。"}}
D.SpellTexts[215287]={Aura={["56353fc0b7105e6d:7"]="定身。"}}
D.SpellTexts[215288]={Description={["fc153cf62c738ca5:167"]="艾乐瑞瑟用痛苦之网将两个目标相连。对相连目标造成伤害的100%会被反射给你。\r\n\r\n目标分离超过20码后，反射的伤害会提高。"}}
D.SpellTexts[215310]={Aura={["808282769b863eb7:38"]="攻击有几率造成火焰伤害。"}}
D.SpellTexts[215313]={Aura={["920f767c3a19035d:27"]="强化潜行侦测。"}}
D.SpellTexts[215315]={Description={["91bb41a577f10680:103"]="施法者驾驭风的力量，并将其引导至敌人身上。被强风击中的受害者会被向后击退。"}}
D.SpellTexts[215319]={Description={["51030b64f0058cd1:38"]="从敌人身侧面向其发动刺击，使其中毒。"}}
D.SpellTexts[215320]={Description={["81c2b704e08b25c9:34"]="召唤一个地狱火协助你战斗。"}}
D.SpellTexts[215329]={Description={["e2a3605a0e8367e1:14"]="装进箱子。"},Aura={["57762cfa7a72cf07:9"]="在箱子里。"}}
D.SpellTexts[215345]={Description={["4d910eb290b8cb8d:32"]="召唤一只失落已久的角鹰兽。"}}
D.SpellTexts[215346]={Aura={["3bb959c1ad34bd98:20"]="持有维库之矛。"}}
D.SpellTexts[215348]={Description={["2efe18c8e8efff1f:77"]="发动一系列的快速攻击，对施法者前方锥形区域内的敌人造成物理伤害。"}}
D.SpellTexts[215349]={Description={["21191007e65e1d9c:75"]="发动一系列的快速攻击，对陶森前方的敌人造成极高的物理伤害。"},Aura={["570ee8d9298a5240:23"]="快速攻击敌人。"}}
D.SpellTexts[215354]={Rank={["1044fc4216ed2ac5:5"]="等级 1"}}
D.SpellTexts[215355]={Rank={["1044fc4216ed2ac5:5"]="等级 1"}}
D.SpellTexts[215359]={Description={["31b6c3d7e8c9375e:30"]="打开一个夜之子法术屏障。"}}
D.SpellTexts[215364]={Description={["36eb81e80a1a1f1b:29"]="对一名敌人造成物理伤害。"}}
D.SpellTexts[215367]={Aura={["8fe6141d6b1c8ce6:51"]="陶森非常强大，每次近战攻击成功命中都会获得能量。"}}
D.SpellTexts[215373]={Description={["00b5c110f7f7fad5:89"]="陶森挥出一记强力的上勾拳，对前方锥形区域内的敌人造成大量的物理伤害。"}}
D.SpellTexts[215378]={Aura={["71a2277eb5a8ea09:19"]="被包围在邪能之中。"}}
D.SpellTexts[215385]={Description={["3f46230ee7ffa92b:39"]="对隐藏的敌人造成神圣伤害并显示其位置。"}}
D.SpellTexts[215395]={Description={["0fde2a329a50cebb:59"]="对施法者前方的所有敌人造成物理伤害，并击昏他们。"},Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[215403]={Aura={["920f767c3a19035d:27"]="强化潜行侦测。"}}
D.SpellTexts[215429]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[215435]={Description={["fc19f0cd4e23f7de:68"]="附近的瓦拉加尔守护着你，使你免疫昏迷与打断效果。"},Aura={["eb120806b3cd8e9b:56"]="使附近的盟友对昏迷与打断免疫。"}}
D.SpellTexts[215440]={Description={["8f3d407ad6ad1741:81"]="施法者制造出一个强烈的压力爆发，将附近所有的敌人都炸到空中。"}}
D.SpellTexts[215442]={Description={["da04a10e8b7022cb:66"]="撕碎敌人，造成物理伤害，并使目标流血。 "}}
D.SpellTexts[215448]={Aura={["49c01acb8441ebb0:32"]="免疫昏迷和打断效果。"}}
D.SpellTexts[215450]={Description={["be7edbb2ad5d147b:53"]="向前喷吐一片水晶尘屑，造成奥术伤害。"}}
D.SpellTexts[215453]={Description={["88f1a18f5de7105e:114"]="祝踏岚带领着影踪派努力保护潘达利亚不受煞的侵害，他是一名技艺非凡的勇士，也是一位无畏的领袖。"},Aura={["fa68637c43931b1d:45"]="祝踏岚是速度、敏捷与力量的大师。"}}
D.SpellTexts[215488]={Description={["d3dfdce2e585edd7:60"]="对施法者前方锥形区域内的所有敌人造成物理伤害。"}}
D.SpellTexts[215490]={Description={["62087984c57920df:54"]="收集野蛮角斗士板甲套装的外观。"},Rank={["684f7cfc8f2ac745:11"]="幻化套装"}}
D.SpellTexts[215535]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[215536]={Description={["c398422349b45cd0:100"]="收藏《德拉诺之王》所有挑战模式地下城的黄金级评价奖励的所有武器的外观。"}}
D.SpellTexts[215545]={Description={["8a3aff9b5ba92542:43"]="召唤或解散一只可供骑乘的血牙寡妇蜘蛛。"}}
D.SpellTexts[215558]={Description={["b13b1292b3ac3061:40"]="召唤或解散一只可供骑乘的骑乘巨鼠。"}}
D.SpellTexts[215560]={Description={["787219c43f013edb:42"]="右键点击以召唤或解散这个小伙伴。"}}
D.SpellTexts[215598]={Description={["14c50ec4a7413a95:96"]="用神圣的力量强化武器，攻击和施法时有几率重击恶魔，造成额外的神圣伤害。"},Aura={["e56a6304bfb70e7d:38"]="击中后有一定几率造成额外的神圣伤害。"}}
D.SpellTexts[215601]={Description={["85ba81bdb7535d44:98"]="用神圣的力量强化武器，攻击和施法时有几率重击敌人，造成额外的神圣伤害。"},Aura={["e56a6304bfb70e7d:38"]="击中后有一定几率造成额外的神圣伤害。"}}
D.SpellTexts[215603]={Description={["03ef4840e18d0cf5:75"]="施法者向锥形区域喷出火焰吐息。任何被火焰击中的敌人都会受到火焰伤害。"}}
D.SpellTexts[215604]={Description={["03ef4840e18d0cf5:75"]="施法者向锥形区域喷出火焰吐息。任何被火焰击中的敌人都会受到火焰伤害。"},Aura={["3d9627bfd1b44104:22"]="每秒一次火焰伤害。"}}
D.SpellTexts[215606]={Description={["85ba81bdb7535d44:98"]="用神圣的力量强化武器，攻击和施法时有几率重击敌人，造成额外的神圣伤害。"},Aura={["e56a6304bfb70e7d:38"]="击中后有一定几率造成额外的神圣伤害。"}}
D.SpellTexts[215618]={Description={["af2dc2d62f82e67f:81"]="施法者摆动尾巴，将身后所有的敌人击退，并造成物理伤害。"}}
D.SpellTexts[215626]={Description={["f8868146c3861ae3:79"]="施法者挥舞利爪，将所有敌人击飞，并造成物理伤害。"}}
D.SpellTexts[215633]={Description={["deaf4c1d16ec3ca4:47"]="烹煮一只生物的骨头。使骨头从内部溶化。"},Aura={["76d099835b2a3b8c:8"]="溶化。"}}
D.SpellTexts[215652]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[215664]={Aura={["7548450309cd002c:14"]="被冻结在原地。"}}
D.SpellTexts[215666]={Description={["02a482b11df91d4c:67"]="喷射的水流，造成冰霜伤害，并将施法者的当前目标击退。"}}
D.SpellTexts[215670]={Aura={["e0d7fd07373b9814:45"]="承担一部分其他敌人所受的伤害。"}}
D.SpellTexts[215674]={Description={["45c22cd84feccf83:50"]="征调一群野生小鬼为你执行任务。"}}
D.SpellTexts[215679]={Description={["d78e24ec39d8f679:69"]="熔岩流淌在地面上，对站在其中的敌人造成火焰伤害。"}}
D.SpellTexts[215687]={Description={["640bb9f072136df1:28"]="将你传送至紫罗兰监狱。"}}
D.SpellTexts[215691]={Description={["f60b54a2a8d7e825:67"]="召唤一个不稳定的元素，元素会锁定一个敌人并向其移动。"}}
D.SpellTexts[215694]={Description={["b126ed7aacd97fa1:65"]="爆炸，造成火焰伤害并留下一个燃烧的熔岩之池。"}}
D.SpellTexts[215803]={Description={["10d7c3693d0503aa:46"]="向前方发动直线冲锋，造成物理伤害。"}}
D.SpellTexts[215808]={Description={["64efc894233c8e31:47"]="射出一枚熔岩之箭，对敌人造成火焰伤害。"}}
D.SpellTexts[215717]={Description={["193017cc6e3bb649:177"]="施法者喷发出剧毒粘液，对敌人造成自然伤害并击退他们。\r\n\r\n在地面上制造一滩淤泥，随着时间的推移而扩大，对站在其中的敌人每秒造成自然伤害。"},Aura={["8a227ec4977f59f9:32"]="每秒造成一次自然伤害。"}}
D.SpellTexts[215719]={Description={["3bec5f84e863bc39:61"]="征调一群邪能愤怒卫士恶魔为你执行任务。"}}
D.SpellTexts[215724]={Description={["3e619f7bde51804e:78"]="召唤一个暗影陷阱，触发时造成暗影伤害，并将敌人击退。"},Aura={["3e619f7bde51804e:78"]="召唤一个暗影陷阱，触发时造成暗影伤害，并将敌人击退。"}}
D.SpellTexts[215726]={Description={["d62377d2fc1f1601:32"]="在乌瑟尔之墓内放下一份祭品。"},Aura={["d62377d2fc1f1601:32"]="在乌瑟尔之墓内放下一份祭品。"}}
D.SpellTexts[215728]={Description={["d62377d2fc1f1601:32"]="在乌瑟尔之墓内放下一份祭品。"},Aura={["d62377d2fc1f1601:32"]="在乌瑟尔之墓内放下一份祭品。"}}
D.SpellTexts[215732]={Description={["7049a5e932f49828:43"]="造成暗影伤害并将目标击退。"},Aura={["7049a5e932f49828:43"]="造成暗影伤害并将目标击退。"}}
D.SpellTexts[215734]={Description={["a36f87afb0f9b7be:33"]="在格罗姆的纪念碑前放下一份祭品。"},Aura={["a36f87afb0f9b7be:33"]="在格罗姆的纪念碑前放下一份祭品。"}}
D.SpellTexts[215735]={Description={["a36f87afb0f9b7be:33"]="在格罗姆的纪念碑前放下一份祭品。"},Aura={["a36f87afb0f9b7be:33"]="在格罗姆的纪念碑前放下一份祭品。"}}
D.SpellTexts[215740]={Description={["5ecdc3afdcaeeb16:48"]="将3块增幅器碎片组合成一个奥术增幅器。"}}
D.SpellTexts[215741]={Description={["d01d61fd7c4113f8:94"]="施法者跳起来后将双爪扑下，对施法者前方的所有敌人造成物理伤害。"}}
D.SpellTexts[215745]={Description={["722fb3a0e81e953b:60"]="你的攻击有一定几率召唤一个瑟芬崔斯克的子嗣来协助你作战。"}}
D.SpellTexts[215746]={Aura={["9a2cd2fa3045010b:9"]="沉默。"}}
