D.SpellTexts[215751]={Aura={["7e59689c4b288d97:20"]="重新组合粒子"}}
D.SpellTexts[215757]={Description={["7e1c40058c1fc85e:36"]="召唤彼提落在你的肩上。"},Aura={["4dcca03879d81b9f:13"]="彼提鸟..."}}
D.SpellTexts[215758]={Description={["146c6297f7d41522:30"]="召唤一个小鬼协助施法者作战。"}}
D.SpellTexts[215762]={Description={["261075a2fcd0dbe9:87"]="召唤一连串的邪能宝珠环绕在敌人周围向其移动，在接触时发生爆炸，造成火焰伤害。"}}
D.SpellTexts[215764]={Description={["53f38c8c2f3bcf6f:108"]="召唤一颗邪能能量宝珠，宝珠会向其目标移动并爆炸，对附近敌人造成火焰伤害。"}}
D.SpellTexts[215766]={Description={["2f021a6c57bf6645:41"]="对施法者附近的所有敌人造成火焰伤害。"}}
D.SpellTexts[215767]={Description={["32897e2d744de176:10"]="热身。"}}
D.SpellTexts[215768]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
