D.SpellTexts[216920]={Description={["9df1c590ffe0e189:126"]="将你传送至守护者大厅。\r\n\r\n在守护者大厅施放此技能将把你传送回出发点附近。"}}
D.SpellTexts[216923]={Description={["e2506490afb03bdd:268"]="作为烈日行者中资格最老的圣骑士，奥伯妮·亮鬃将她那些渴求知识的族人紧密地团结在自己的周围。圣光的真义究竟是什么？为什么它会将力量赐予我们？这些问题如火焰一般在奥伯妮心中燃烧，一切阻挡她追寻答案的人或事，都会被她毫不犹豫地扫除。"}}
D.SpellTexts[216924]={Description={["e2506490afb03bdd:268"]="作为烈日行者中资格最老的圣骑士，奥伯妮·亮鬃将她那些渴求知识的族人紧密地团结在自己的周围。圣光的真义究竟是什么？为什么它会将力量赐予我们？这些问题如火焰一般在奥伯妮心中燃烧，一切阻挡她追寻答案的人或事，都会被她毫不犹豫地扫除。"}}
