D.SpellTexts[216926]={Description={["e2506490afb03bdd:268"]="作为烈日行者中资格最老的圣骑士，奥伯妮·亮鬃将她那些渴求知识的族人紧密地团结在自己的周围。圣光的真义究竟是什么？为什么它会将力量赐予我们？这些问题如火焰一般在奥伯妮心中燃烧，一切阻挡她追寻答案的人或事，都会被她毫不犹豫地扫除。"}}
D.SpellTexts[216934]={Description={["834597cf030ee3e2:89"]="召唤一颗折磨宝珠，除非玩家面向宝珠，否则宝珠会周期性地凝视玩家。"}}
D.SpellTexts[216942]={Description={["d735ae7a8a434239:61"]="命令你的枯法者跟随着你，并集中攻击你的目标。"}}
D.SpellTexts[216944]={Description={["cf71f492086bf17b:57"]="施法者召唤暗影化身，偷取敌人的光。"},Aura={["84062610f0bf1f09:27"]="你的光即将被偷取。"}}
