D.SpellTexts[216995]={Aura={["b55aef7d4a06e028:36"]="你的下一个氤氲之雾变为瞬发。"}}
D.SpellTexts[216999]={Description={["49e74d72dd681ce5:79"]="引起多次奥术引爆，造成奥术伤害，并将目标击飞到空中。"}}
