D.SpellTexts[217006]={Aura={["5089c0c43efbdebf:26"]="你的下一次活血术将不消耗法力。"}}
D.SpellTexts[217017]={Description={["42ad57cd5148b798:7"]="入睡。"},Aura={["42ad57cd5148b798:7"]="入睡。"}}
