D.SpellTexts[217030]={Description={["2ddf7bad0fb02f7e:58"]="全力冲撞敌人，造成物理伤害。"}}
D.SpellTexts[217040]={Description={["f0dba20948a8418a:87"]="传送到一个附近的地点，移除所有威胁值，在原地留下一个暗影幻象。"},Aura={["f0dba20948a8418a:87"]="传送到一个附近的地点，移除所有威胁值，在原地留下一个暗影幻象。"}}
D.SpellTexts[217046]={Aura={["12cc36b73cbb1b34:39"]="一个虚空残渣将视线锁定在了你的身上..."}}
D.SpellTexts[217053]={Description={["7d0d73759dfc2ba0:79"]="发动一次毁灭性打击，对施法者前方的所有敌人造成物理伤害。"}}
D.SpellTexts[217078]={Description={["67e6706cd61bce6d:26"]="在苍穹要塞为荣耀而战。"},Aura={["6d1bd767a35146ca:36"]="当前击杀数量。死亡时会重置此计数。"}}
