D.SpellTexts[217101]={Aura={["90c21499d1dda69c:56"]="在伊利达雷棱堡时免受疲劳效果影响。"}}
D.SpellTexts[217102]={Aura={["100a5660ef9b948f:66"]="使用邪能之槌号舰炮消灭下方燃烧军团的部队。"}}
