D.SpellTexts[217115]={Aura={["703f211b5eb0d0da:37"]="一阵雷电风暴，干扰目标的选中。"}}
D.SpellTexts[217124]={Description={["306d8029f3a3da1c:88"]="亵渎目标脚下的土地，并制造出一片带有锋利棘刺的石南草丛，造成暗影伤害。"}}
D.SpellTexts[217134]={Description={["d23ad00cfef27db1:81"]="恐惧魔王对前方的目标发动顺劈，造成暗影伤害，并吸收同等数量的生命。"},Aura={["d23ad00cfef27db1:81"]="恐惧魔王对前方的目标发动顺劈，造成暗影伤害，并吸收同等数量的生命。"}}
