D.SpellTexts[217414]={Description={["d95fb87dd8c1f336:71"]="四下挥舞，释放能量并对附近的所有敌人造成奥术伤害。"}}
D.SpellTexts[217434]={Description={["716c67b793444a72:116"]="召唤一连串的奥术宝珠，这些宝珠会随机选择地点。在到达目标位置后，宝珠会发生爆炸，造成奥术伤害。"}}
