D.SpellTexts[217455]={Description={["8f91bff355119dfc:53"]="收集原始胜利的武器附魔外观。"}}
D.SpellTexts[217457]={Description={["73e63958c40de865:78"]="制造一个能量宝珠，对冲击点附近的所有敌人造成奥术伤害。"}}
D.SpellTexts[217458]={Description={["fa097d8d858bc964:58"]="在现实中撕扯出孔洞，打开传送门，通往马顿的邪能之槌号。"}}
D.SpellTexts[217461]={Description={["b440aea9c96a1e3c:80"]="喝下之后可以一瞥灵魂国度的景象，持续5分钟。高度数的酒精饮料。"},Aura={["b989f0c1cbbefdea:25"]="能够一瞥另一个国度。"}}
D.SpellTexts[217471]={Description={["c3296cd50cafbbc8:65"]="爆发出能量冲击，对附近所有敌人造奥术伤害。"}}
D.SpellTexts[217480]={Description={["b6a7082c9a95f7d3:40"]="使用混乱能量腐蚀并控制目标。"},Aura={["b6a7082c9a95f7d3:40"]="使用混乱能量腐蚀并控制目标。"}}
D.SpellTexts[217481]={Description={["90a3a1f6afe5f8d3:59"]="喝下之后会散发出浓烈的味道，持续5分钟。高度数的酒精饮料。"},Aura={["38bb9afeebaeffdb:17"]="风暴即将来临..."}}
D.SpellTexts[217489]={Description={["71b781fa01f18a19:41"]="像食人魔一样畅饮，持续5分钟。高度数的酒精饮料。"},Aura={["130de6bddb423872:38"]="你喝酒的样子就像食人魔一样。"}}
D.SpellTexts[217490]={Description={["60852c0ec57e887b:48"]="敲击敌人的脑袋，造成物理伤害。"}}
D.SpellTexts[217493]={Description={["0cb8e085f3d794e6:11"]="结束游戏。"}}
D.SpellTexts[217495]={Aura={["f0a350c81785ed97:31"]="每秒受到一次火焰伤害。"}}
D.SpellTexts[217498]={Description={["387448e9dc0b1bce:64"]="喝下这种酒会闪闪发亮，持续5分钟。高度数的酒精饮料。"},Aura={["719eb52ae8531123:28"]="我采集微光草是为了这个？"}}
D.SpellTexts[217504]={Description={["80d32b3a7d59a27f:60"]="喝下这种酒会勃然大怒，持续5分钟。高度数的酒精饮料。"},Aura={["221dfd288c779771:10"]="你见血了。"}}
D.SpellTexts[217518]={Aura={["f0a350c81785ed97:31"]="每秒受到一次火焰伤害。"}}
D.SpellTexts[217519]={Description={["68fa12f65f14db6f:89"]="恶魔传送门变为瞬发，你可以在冷却时间触发之前连续使用两次恶魔传送门。"}}
D.SpellTexts[217551]={Aura={["b672152aa5bc78e9:57"]="遁入虚空，且只能再使用一次恶魔传送门。"}}
D.SpellTexts[217553]={Description={["94d3efa9d908eac6:57"]="不稳定的暗夜井能量将使你损失总生命值的50%。"}}
D.SpellTexts[217563]={Description={["c3f20adca7bee139:61"]="卡拉米尔变形，使用火焰之力摧毁敌人。"},Aura={["c3f20adca7bee139:61"]="卡拉米尔变形，使用火焰之力摧毁敌人。"}}
D.SpellTexts[217583]={Description={["00009f4792206fca:88"]="向敌人引导一阵奥术能量的洪流，造成奥术伤害，并使其移动速度降低。"}}
D.SpellTexts[217593]={Description={["b55e5ffe09e4f42d:127"]="发射一簇炽焰之球，在目标位置制造出活体邪焰。存活期间，活体邪焰会冲击附近的敌人，造成火焰伤害。"}}
D.SpellTexts[217594]={Description={["e4a999b97d43fe8c:63"]="征调一队黑暗收割祈祷者为你执行任务。"}}
