D.SpellTexts[217613]={Description={["2e604b3d5283fcf6:127"]="把在阿苏纳的魔网附近发现的小块魔网水晶研磨成半食用性的水晶碎片。研磨器每次使用之后都需要一定的时间恢复。"}}
