D.SpellTexts[217835]={Description={["a860efd07e7dcc8d:81"]="在你的钓鱼竿上装上诱饵。可以帮你从达拉然的喷泉中钓到某些硬币。"},Aura={["8c8feb2cb381efc5:63"]="在达拉然喷泉中钓鱼时，有更高的几率可以钓到某些硬币。"}}
