D.SpellTexts[217838]={Description={["8a0f3df2ac1762a5:119"]="在你的钓鱼竿上装上这个设备，在你钓鱼的地方制造一个小型漩涡。可以帮你从达拉然的喷泉中钓到某些硬币。"},Aura={["8c8feb2cb381efc5:63"]="在达拉然喷泉中钓鱼时，有更高的几率可以钓到某些硬币。"}}
