D.SpellTexts[217842]={Description={["170686dfd99f08d6:130"]="在你的钓鱼竿上装上水晶。海星可以用吸嘴帮你从达拉然的喷泉中钓上某些硬币。"},Aura={["8c8feb2cb381efc5:63"]="在达拉然喷泉中钓鱼时，有更高的几率可以钓到某些硬币。"}}
