D.SpellTexts[218108]={Description={["7a8d3eb9f126fd5c:18"]="免疫所有伤害。"},Aura={["7a8d3eb9f126fd5c:18"]="免疫所有伤害。"}}
D.SpellTexts[218109]={Description={["1cd5696f9ee41144:68"]="对敌人造成武器伤害再加额外的物理伤害。"}}
