D.SpellTexts[218122]={Description={["53373d0faddf7ae4:52"]="召唤小鬼助战施法者\r\n\r\n\r\n或许？\r\n\r\n我想是吧。。。"}}
D.SpellTexts[218128]={Description={["52af971b028543a8:42"]="在施法者脚下制造一个奥术符文。"}}
D.SpellTexts[218131]={Description={["3bf3f2ecf89a9927:42"]="为目标小队成员穿上女妖装束。"}}
D.SpellTexts[218132]={Description={["1e140486db6de45f:40"]="给目标小队成员穿上女妖装束。"},Aura={["7e8fb58d9c6a884a:72"]="在女妖装束下无法施放法术。\r\n右键单击图标移除此效果。"}}
D.SpellTexts[218142]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[218153]={Description={["1fbf8985865afedc:96"]="风暴召唤者米尔拉与你并肩作战。米尔拉偶尔会召唤一个风暴比克，攻击附近的敌人。"}}
D.SpellTexts[218156]={Description={["60c31587ca099a04:32"]="部队招募消耗降低25%"}}
D.SpellTexts[218164]={Description={["2301dc92240992d9:47"]="移除目标身上所有的中毒和疾病效果。"}}
D.SpellTexts[218174]={Description={["99cbf17ee79dd6b3:39"]="打开藏卷人密室的大门。"}}
D.SpellTexts[218191]={Aura={["72a3b58d5a30eede:21"]="被真正的陷阱困住！"}}
D.SpellTexts[218194]={Description={["cada87aafdf17953:120"]="使你的枯法部队的生命值提高25%。\r\n\r\n此为永久性效果，将在你下次进入大陷坑场景战役时生效。"}}
D.SpellTexts[218195]={Description={["44648156a2c555b1:169"]="你的枯法部队中的一名成员可以穿戴头盔，成为强大的枯法狂战士。\r\n\r\n此为永久性效果，将在你下次进入大陷坑场景战役时生效。"}}
D.SpellTexts[218211]={Description={["e4b356897739b518:20"]="菲娜·伯恩多提尔正在跟随你。"},Aura={["e4b356897739b518:20"]="菲娜·伯恩多提尔正在跟随你。"}}
D.SpellTexts[218216]={Description={["ebb3fd8c5e2c845d:23"]="拉格瓦尔德·龙脉正在跟随你。"},Aura={["ebb3fd8c5e2c845d:23"]="拉格瓦尔德·龙脉正在跟随你。"}}
D.SpellTexts[218227]={Description={["f0c3cf68a69e81a1:38"]="召唤风暴比克攻击你的敌人。"}}
D.SpellTexts[218252]={Description={["cfa229aecc6dac15:138"]="使你的枯法部队在受伤时逃跑的几率降低。\r\n\r\n此为永久性效果，将在你下次进入大陷坑场景战役时生效。"}}
D.SpellTexts[218254]={Description={["d3fc638b96abe7a0:149"]="鼓励你的枯法部队更有效地对敌人发动攻击。\r\n\r\n此为永久性效果，将在你下次进入大陷坑场景战役时生效。"}}
D.SpellTexts[218259]={Description={["74a7176c886cef55:170"]="你的枯法部队中的一名成员可以穿戴头盔，成为强大的枯法怒法者。\r\n\r\n此为永久性效果，将在你下次进入大陷坑场景战役时生效。"}}
D.SpellTexts[218270]={Description={["16410d8ab67ca84f:163"]="你的枯法部队中的一名成员可以佩戴这副眼镜，让它可以看到隐藏的财宝。\r\n\r\n此为永久性效果，将在你下次进入大陷坑场景战役时生效。"}}
D.SpellTexts[218271]={Description={["e8f5a5b70527a640:160"]="你的枯法部队中的一名成员可以佩戴这个圆盘，使其获得强大的魔法能力。\r\n\r\n此为永久性效果，将在你下次进入大陷坑场景战役时生效。"}}
D.SpellTexts[218274]={Description={["ab95aa55b743dcca:34"]="每秒吸取目标的生命。"},Aura={["ab95aa55b743dcca:34"]="每秒吸取目标的生命。"}}
D.SpellTexts[218277]={Description={["6686557fb979ed56:98"]="海达克西斯到来，用水将你浸湿，净化你所有的负面效果，并且立即为你恢复全部的生命值。"}}
D.SpellTexts[218279]={Description={["0ffa28c40aa3af3d:36"]="你的宠物被虚空之力吞噬了。"},Aura={["a21e5f4f0e3148e4:49"]="你的好友将会遗弃你...开玩笑的啦！我爱你！"}}
D.SpellTexts[218281]={Description={["af8a50b14201c09c:19"]="吸收受到的伤害。"},Aura={["af8a50b14201c09c:19"]="吸收受到的伤害。"}}
D.SpellTexts[218292]={Description={["c38b3c243d410de1:198"]="引发暗影能量爆裂，在目标玩家周围造成暗影伤害，并制造出一片暗影浸染之地。进入这片区域的玩家每2秒受到暗影伤害。"}}
D.SpellTexts[218295]={Description={["798c93982bdc29ed:69"]="与损坏的雷霆之怒相结合，修复这把逐风者的祝福之剑。"}}
