D.SpellTexts[218367]={Description={["935bfee96c29a9a0:34"]="将饮用者置于一个恐怖的诅咒之下。"},Aura={["8803cc7cb087e90f:35"]="这是真的，还是只是个可怕的噩梦？"}}
