D.SpellTexts[218371]={Description={["ca4cde1db8a17104:22"]="你能够乘筏子横渡水域。"},Aura={["43bb2d31120353ca:103"]="使你获得能够随波漂流的能力。\r\n\r\n在漂流过程中跳跃可以划动筏子，使你的移动速度最多提高130%。"}}
