D.SpellTexts[218605]={Description={["f1ba47e5b34e5246:150"]="变形为熊形态，不受变形效果影响，产生的威胁值提高。\r\n\r\n变形会让你摆脱移动限制效果。"},Aura={["9d31740b67b5ab2a:25"]="免疫变形效果。"},Rank={["7f5c1454467b72e1:10"]="变形"}}
D.SpellTexts[218612]={Description={["c18a7ec77660c508:69"]="消耗一个灵魂残片会使恶魔尖刺剩余的冷却时间缩短1秒。"}}
D.SpellTexts[218613]={Description={["38c84a16c5fa500b:54"]="对施法者前方锥形区域内的敌人造成物理伤害。"},Aura={["c61d73c3a4cab672:22"]="造成物理伤害。"}}
