D.SpellTexts[218629]={Description={["6ecf2278137f3a7d:161"]="持续在周围召唤卵囊，逐渐成长。成长完毕的卵囊在破裂时会释放出剧毒小蜘蛛。\r\n\r\n艾乐瑞瑟在邪恶伏击期间会使所有卵囊破裂。"}}
D.SpellTexts[218630]={Description={["90f596d6e426d891:88"]="卵囊从地下涌出，包围住一片区域，同时会缓慢地向中心蔓延。"}}
D.SpellTexts[218639]={Description={["c6f800ac09d40549:107"]="攻击会引发烈焰破坏，造成额外的火焰伤害，并在附近位置形成烈焰破坏。"},Aura={["c6f800ac09d40549:107"]="攻击会引发烈焰破坏，造成额外的火焰伤害，并在附近位置形成烈焰破坏。"}}
