D.SpellTexts[218662]={Description={["650f68f96160d4ba:50"]="征调一队[单位]为你执行任务。"}}
D.SpellTexts[218669]={Description={["a46daf4890b356ef:57"]="血肉灰烬效果结束会对附近所有敌人造成火焰伤害。"},Aura={["a46daf4890b356ef:57"]="血肉灰烬效果结束会对附近所有敌人造成火焰伤害。"}}
D.SpellTexts[218670]={Description={["cd441a52c82abd47:367"]="很多人都认为这位臭名昭著的迪菲亚兄弟会头目几年前已经在死亡矿井中丧生。然而，凭借一瓶能让人暂时装死的药剂和一套防火护甲，西部荒野的任性女儿得以逃出生天。此后她加入了一个名为“无冕者”的秘密组织，对政府的强烈叛逆让她在里面如鱼得水。她在组织中的地位迅速提升，成为了一名神秘的“影行者”，坚定地向着自己的复仇大业前进。"}}
D.SpellTexts[218681]={Description={["36b7f2d535c944f4:218"]="食魂者阿莱利是神器夺魂之镰的持有者，她本身就擅长捕获恶魔的灵魂，夺魂之镰还使她获得不可思议的能力。很少有其他人能像食魂者阿莱利这样迅速地让燃烧军团屈膝求饶。"},Aura={["20ca86f3a7e73060:117"]="食魂者阿莱利已经掌握了浩劫恶魔猎手之道。她因其控制恶魔和束缚恶魔灵魂的能力而闻名于世。"}}
D.SpellTexts[218682]={Description={["68fa46e0a2a6fc1d:285"]="在杰斯之前的人生中，在经历仪式的转变成为伊利达雷成员之前，他是一位强大的法师。现在他仍然保留了大部分魔法知识。再加上对体内涌动的邪能能量的掌握，他为伊利达雷制造了诸多有用的设备，例如虚空坩埚、恶魔陷阱和守卫。"},Aura={["9a83428d5ab87bc0:170"]="杰斯·织暗已经掌握了复仇恶魔猎手之道。他最出名的地方在于执行邪能仪式的能力，并且为伊利达雷提供了许多富有创造性的方法，用以解决棘手的难题。"}}
