D.SpellTexts[219622]={Description={["a015c9d696069e7b:22"]="变形成海象人。"},Aura={["1ef67d53b54b8f0e:93"]="变形成海象人。\r\n\r\n变形后，你可以在下水道的开阔水域钓到盲目之眼。"}}
D.SpellTexts[219626]={Description={["4d899066c5644863:21"]="在雪球中畅游。"},Aura={["1bc98b6eaaf3f365:32"]="庆祝冬幕节的奇迹！"}}
D.SpellTexts[219630]={Description={["03715424b2631f1d:32"]="变形术的目标会稍变大一些。"}}
D.SpellTexts[219641]={Aura={["b419339856b89af1:22"]="绝非小猫小狗。"}}
D.SpellTexts[219649]={Description={["637cc742cc2210ed:56"]="造成极限混乱伤害。\r\n\r\n或有意想不到的副作用。"},Aura={["e467a5e7783ba42e:34"]="遭遇意想不到的副作用。"}}
D.SpellTexts[219654]={Description={["04cddec628427a91:62"]="攻击会对施法者前方的敌人造成额外的火焰伤害。"}}
D.SpellTexts[219657]={Description={["5cf43db75b3f681e:86"]="发动一连串的攻击，对施法者前方锥形范围内的敌人造成火焰伤害。"}}
D.SpellTexts[219772]={Aura={["8ded124befc1a92c:33"]="虚空形态下停止消耗狂乱值。"}}
D.SpellTexts[219666]={Description={["c160f7d8b4a41ea7:36"]="召唤一个奥术炸弹轰炸敌人。"}}
D.SpellTexts[219669]={Description={["d7e88f8df88c1a36:32"]="你进入更深层的鬼魂状态。"}}
D.SpellTexts[219674]={Description={["90edd3129e9e701f:32"]="快速射击，造成奥术伤害。"}}
D.SpellTexts[219676]={Description={["6c880bf476c90fc3:29"]="自动射击目标。"},Aura={["671d514f94402952:18"]="射击目标。"}}
D.SpellTexts[219678]={Description={["6b2f204c41a261f3:32"]="将你的烟雾弹换成闪光弹！"}}
D.SpellTexts[219680]={Aura={["8725a32dadf6ad66:9"]="流血。"}}
D.SpellTexts[219693]={Description={["3dac90397bc8c05c:34"]="一大杯老酒也能让目标晕得不行。"}}
D.SpellTexts[219700]={Description={["b946204e9494f8a7:26"]="召唤伊墨瑞尔·影卫。"}}
