D.SpellTexts[219713]={Description={["fe2f4d506815854f:36"]="你的破碎灵魂已经沾染上了邪能。"}}
D.SpellTexts[219723]={Description={["70f63f8e35aaf921:20"]="变形成鹰身人。"},Aura={["f553fd1744154a42:96"]="变形成鹰身人。\r\n\r\n在达拉然下水道中变形后，你能够飞行一小段时间。"}}
D.SpellTexts[219725]={Description={["9632dbc573a4ef30:21"]="变形成狗头人。"},Aura={["f53ed3f4f0a47c33:110"]="变形成狗头人。\r\n\r\n变形后，你可以在达拉然下水道里，从敌人的尸体上收集蜡烛。"}}
D.SpellTexts[219726]={Description={["68d8d1be9de38ab5:20"]="变形成树妖。"},Aura={["1faa82dec64a07a3:95"]="变形成树妖。\r\n\r\n变形后，你可以在达拉然下水道里使用自然冲锋。"}}
D.SpellTexts[219730]={Description={["bd111a164bb0b5e7:26"]="变形成堕夜精灵。"}}
D.SpellTexts[219731]={Description={["8b53ecf0d03ec8f1:20"]="变形成海巨人。"},Aura={["a3edbfd4c76aac2b:69"]="变形成海巨人。\r\n\r\n变形后，你的伤害和生命值都会提高两倍。"}}
