D.SpellTexts[219845]={Description={["bd111a164bb0b5e7:26"]="变形为堕夜精灵。"},Aura={["5e734aad35731a70:193"]="变形成夜之子，急速提高10%。\r\n\r\n生命值降至75%以下时，你会变为堕夜精灵，急速额外提高10%。\r\n\r\n生命值降至50%以下时，你会变为枯法者，急速额外提高10%。"}}
D.SpellTexts[219852]={Description={["902333a6d5dcc063:89"]="射出爆烈弹雨，对施法者前方锥形区域内的所有敌人造成火焰伤害。"}}
D.SpellTexts[219856]={Description={["fe5f14a7e54916da:20"]="与小精灵建立联系。"},Aura={["fb69fcbfc9ba1c46:16"]="与小精灵联系在一起。"}}
