D.SpellTexts[219921]={Description={["bdf5a7a61e50a8c7:31"]="把蔬菜扔进哈维的罐子里。"}}
D.SpellTexts[219930]={Description={["b97298571be9665a:39"]="对所有附近的敌人造成暗影伤害。"},Aura={["b97298571be9665a:39"]="对所有附近的敌人造成暗影伤害。"}}
D.SpellTexts[219935]={Description={["eda2ffaf1b42dcac:26"]="把螃蟹扔进哈维的罐子里。"}}
D.SpellTexts[219940]={Aura={["ee5e419b93115bbc:61"]="制造一个暗影流星，当光环效果结束时会落在目标位置。"}}
D.SpellTexts[219944]={Description={["a6b11ed8305f755f:47"]="造成暗影伤害，由所有目标均摊。"},Aura={["a6b11ed8305f755f:47"]="造成暗影伤害，由所有目标均摊。"}}
D.SpellTexts[219946]={Description={["9fccd01b2bd6a034:28"]="把谷物扔进哈维的罐子里。"}}
D.SpellTexts[219958]={Description={["70b88bcd21543126:34"]="受到伤害会产生爆裂印记。"},Aura={["70b88bcd21543126:34"]="受到伤害会产生爆裂印记。"}}
D.SpellTexts[219961]={Description={["349aedae8e21b799:51"]="对施法者前方的所有敌人造成暗影伤害。"}}
D.SpellTexts[219963]={Aura={["2ddd0278935431e5:22"]="被永久控制。"}}
D.SpellTexts[219978]={Description={["7f7f6cce4f99058f:132"]="阅读可以让你获得关于神器的新知识，提高获得神器能量的速度。这些笔记可以使你的神器知识等级提高到40级。"}}
D.SpellTexts[219987]={Description={["1337efb5136f26a4:41"]="撕扯敌人，造成物理伤害。"}}
D.SpellTexts[219988]={Description={["8b53ecf0d03ec8f1:20"]="变形成海巨人。"},Aura={["30d87fba5af1e22b:121"]="当你位于一个足以容纳海巨人的空间时，你会变形成一个海巨人。\r\n\r\n变形后，你的生命值和伤害都会提高两倍。"}}
D.SpellTexts[219998]={Description={["fb993b2a0fec3d55:78"]="艾迪正在书写你所有的功绩。声望收益提高5%。"},Aura={["fb993b2a0fec3d55:78"]="艾迪正在书写你所有的功绩。声望收益提高5%。"}}
D.SpellTexts[220004]={Aura={["7d5d9ff20183211b:14"]="奥术协调。"}}
D.SpellTexts[220006]={Aura={["cbdc5feeabcd090b:12"]="火焰协调。"}}
D.SpellTexts[220007]={Aura={["c2fc8a363ec12db9:13"]="冰霜协调。"}}
D.SpellTexts[220011]={Description={["58f6577a9593d877:36"]="移除一个敌人不可逾越的障碍。"}}
D.SpellTexts[220015]={Aura={["9c9b4d7eae52d7eb:7"]="免疫。"}}
D.SpellTexts[220021]={Description={["60c1e113a55bf55c:55"]="在下水道为玩家摆下一席大餐，\r\n\r\n可以喂饱25名玩家。"}}
D.SpellTexts[220025]={Description={["17ac919dde49d27a:12"]="喂饱某人。"}}
D.SpellTexts[220039]={Description={["c02406d2380a5e41:27"]="重新召集魔法屏障。"}}
D.SpellTexts[220040]={Description={["d6b65d00304f6531:62"]="爆炸产生软泥云雾，对附近敌人造成自然伤害。"}}
D.SpellTexts[220048]={Description={["11b2e772f435a419:99"]="让充电火花跟随目标，每隔一段时间冲击地面，造成自然伤害。"}}
D.SpellTexts[220052]={Description={["4f3bfdab31e88bae:36"]="将施法者传送到群星庭院。"}}
D.SpellTexts[220058]={Description={["bbc1785157d3c390:164"]="使用时会获得圣光之赐。如果你受到致命伤害，圣光会使你恢复全部的生命值，并击退附近的敌人。\r\n\r\n只能在破碎群岛和阿古斯使用。"},Aura={["dae6bbac12483417:35"]="圣光保护你不会受到致命的伤害。"}}
D.SpellTexts[220060]={Description={["7dc5b1ee634024a9:62"]="一阵刺耳的嚎叫，对附近的敌人造成物理伤害。"}}
D.SpellTexts[220063]={Aura={["ac05b072b5e7a223:29"]="满溢着借来的能量。"}}
D.SpellTexts[220069]={Description={["e48592000e2cf5f1:60"]="附近的盟友和敌人可以看到你携带着上古神器。"},Aura={["9f75f13d317ea192:48"]="携带上古神器。击杀后可以拾取。"}}
D.SpellTexts[220074]={Description={["feae4cec8ff3d59b:43"]="向前方喷吐虚空软泥，造成暗影伤害。"}}
D.SpellTexts[220078]={Description={["fdfc9e121db2edf3:40"]="猛击地面，造成物理伤害。"}}
D.SpellTexts[220079]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[220081]={Description={["7bb601ed478925e2:72"]="使用破法者打击敌人的喉部，打断正在施放的所有法术。"}}
D.SpellTexts[220082]={Description={["cd3f59ed7ca3a8ae:51"]="对所有敌人造成自然伤害并将其击退。"}}
D.SpellTexts[220083]={Description={["4ade90db216323c8:39"]="激活滑翔时你将展开黄色的双翼。"}}
D.SpellTexts[220089]={Description={["17ae41b45221ef87:58"]="对施法者前方锥形区域内的所有敌人造成自然伤害。"}}
D.SpellTexts[220092]={Aura={["aae902a546450452:22"]="受到冰霜魔法的强化。"}}
D.SpellTexts[220093]={Aura={["cf9351fde24bf40a:21"]="受到火焰魔法的强化。"}}
D.SpellTexts[220094]={Aura={["dc3d3dc17ac83a9a:23"]="受到奥术魔法的强化。"}}
D.SpellTexts[220095]={Aura={["536784ae07528edb:20"]="受到邪能魔法的强化。"}}
D.SpellTexts[220101]={Description={["f3e2c3f542c066f8:28"]="造成大量自然伤害。"}}
D.SpellTexts[220107]={Aura={["c17d2c2706c53b0e:7"]="冻结。"}}
D.SpellTexts[220110]={Description={["a761f7d13dd90274:172"]="激活符文，获得黑暗遮蔽效果。如果你受到致命伤害，黑暗会将你恢复到最大生命值，并击退附近所有的敌人。\r\n\r\n只能在破碎群岛和阿古斯使用。"},Aura={["6f90a14f19be24e2:38"]="黑暗保护你不会受到致命的伤害。"}}
D.SpellTexts[220114]={Description={["b90619e78a55cce6:109"]="吃下神秘的果实让你病入膏肓。你为什么要吃那玩意？你当时是怎么想的？你本不该那么做..."},Aura={["0cdb5882f9adb3e9:20"]="你感觉不太好..."}}
D.SpellTexts[220124]={Description={["87b9a1454b578e92:14"]="骑乘一只下水道老鼠。"}}
D.SpellTexts[220126]={Description={["b7ea9c77d9306ff0:31"]="大法师茉德拉与你并肩作战。"}}
D.SpellTexts[220128]={Description={["8fc684a791d12a94:60"]="将敌人冻结在原地。受到伤害可能会打断冻结效果。"},Aura={["7548450309cd002c:14"]="被冻结在原地。"}}
D.SpellTexts[220134]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[220136]={Description={["7937ddb460ddb041:99"]="使用疾跑之后的3秒内如果不受到任何伤害，将会自动使用消失且不触发消失的冷却时间。"}}
D.SpellTexts[220141]={Description={["afe4a8aa726908b7:71"]="猛击地面，造成物理伤害，并击退附近所有敌人。"}}
D.SpellTexts[220143]={Rank={["5e500f93cabfbb92:8"]="神器"}}
D.SpellTexts[220145]={Description={["d3dfdce2e585edd7:60"]="对施法者前方锥形区域内的所有敌人造成物理伤害。"}}
D.SpellTexts[220150]={Description={["08955406430c3cd3:122"]="亡灵骑兵柯提斯命令他的蝙蝠在他前方释放3次音波能量冲击。每次冲击对其接触的所有敌人造成物理伤害。"}}
D.SpellTexts[220168]={Description={["8974542626aa5289:144"]="猛击地面，造成火焰伤害并击退附近所有敌人，同时向随机方向发射水晶碎片，命中时造成火焰伤害。"}}
D.SpellTexts[220172]={Description={["22d6694630e343ef:184"]="在有些人心目中，瓦莉拉是这个世界上最优秀的刺客。迦罗娜可能有不同的意见，但瓦莉拉的光辉记录本身即是最好的证明。她的脾气也是名声在外，所以最好不要触怒她。"},Aura={["01177a1816c358ef:122"]="瓦莉拉·萨古纳尔掌握了刺杀潜行者之道。她擅长使用毒药，同时也是一名近战格斗大师。"}}
D.SpellTexts[220175]={Description={["0f92335ef59e3335:71"]="施法者瞬间跨越时空，重新出现在敌人背后。"}}
D.SpellTexts[220181]={Description={["bae9c443c5b40ca6:71"]="选择你的一名勇士，使其完成一个任务的成功率提高。"}}
D.SpellTexts[220188]={Description={["8a631b264f0320d1:98"]="通过魔网能量节点时，你的速度会逐渐增加。但是转弯时会被减速。"}}
D.SpellTexts[220191]={Description={["3893ba1e114a0ccd:58"]="朝一个方向冲锋，对击中的目标造成奥术伤害。"},Aura={["06c1c518c24c4f75:21"]="造成奥术伤害。"}}
D.SpellTexts[220195]={Description={["bae9c443c5b40ca6:71"]="选择你的一名勇士，使其完成一个任务的成功率提高。"}}
D.SpellTexts[220197]={Description={["59936deb0c1927d6:142"]="猛击地面，造成冰霜伤害并冻结附近所有敌人，同时向随机方向发射水晶碎片，命中时造成冰霜伤害。"}}
D.SpellTexts[220207]={Aura={["bf4dee2b18869d14:8"]="正在治疗。"}}
D.SpellTexts[220208]={Description={["23104188224a9655:18"]="给予某人一个坐骑。"}}
D.SpellTexts[220213]={Description={["4322556b224f5acc:35"]="米尔豪斯·法力风暴与你并肩作战。"}}
D.SpellTexts[220226]={Description={["4d4c5f3cba8a9683:41"]="激活滑翔时你将展开破碎的双翼。"}}
D.SpellTexts[220227]={Description={["0973815492fb2a9f:33"]="对附近的敌人造成自然伤害。"}}
D.SpellTexts[220228]={Description={["3b25ca10a8e9dcd7:38"]="激活滑翔时你将展开绿色的双翼。"}}
D.SpellTexts[220229]={Description={["77bb96af9b2dd972:106"]="放置一箱骑乘巨鼠缰绳，你和其他玩家可以在下水道中使用，以获得坐骑。\r\n\r\n内含25只坐骑。"}}
D.SpellTexts[220234]={Description={["5b2dd8e3616f0270:22"]="将目标变为石头。"},Aura={["9a0f810b8152e890:17"]="被魔法石化。"}}
D.SpellTexts[220235]={Description={["e1b322f269592015:48"]="召唤阿斯特瑞克斯为施法者作战，直到被解散。"}}
D.SpellTexts[220236]={Description={["3ba9005fea621fbe:94"]="在靠近劳拉·马利的地面上放一些宠物，你和其他玩家可以与之战斗并将其捕获。\r\n\r\n内含4只宠物。"}}
D.SpellTexts[220237]={Description={["b4bc5287c06710d8:93"]="可在达拉然下水道里的水中使用，使鱼来到水面。\r\n\r\n效果持续5分钟。"}}
D.SpellTexts[220240]={Description={["49406ca5dc5e9694:74"]="邪能改变了你的幽灵视觉，你看到的所有敌人都笼罩在邪能光线之中。"}}
D.SpellTexts[220244]={Description={["1ede2aff8479d86a:67"]="虚空沾染了你的幽灵视觉，你看到的敌人都被蒙在暗影之中。"}}
D.SpellTexts[220253]={Description={["6809360f7877d9ec:77"]="将鳄鱼从达拉然下水道的管道里冲洗出去。\r\n\r\n效果持续5分钟。"}}
D.SpellTexts[220255]={Aura={["91aa8c1907a2d1bc:18"]="减缓坠落速度。"}}
D.SpellTexts[220260]={Description={["bec576568ed0c837:60"]="唤醒达拉然下水道的老鼠。\r\n\r\n效果持续5分钟。"}}
D.SpellTexts[220265]={Description={["88b70db9cf8b3612:43"]="召唤一大批小鬼进入到下水道中。"}}
D.SpellTexts[220266]={Description={["9df3a19d5884dfa8:63"]="召唤几名寡妇潜行者的追随者，进入到达拉然下水道中。"}}
D.SpellTexts[220273]={Description={["e37c0cb9c4be3fd6:167"]="极大提高达拉然下水道中一名首领的生命值和伤害值。同样也会提高被击杀时掉落的盲目之眼的数量。\r\n\r\n无法用于生命值低于90%的首领。"}}
D.SpellTexts[220279]={Description={["b6cc4f8cc3e06a83:38"]="你的疾跑会在身后留下一道烟雾尾迹。"}}
D.SpellTexts[220291]={Description={["724070b627c90847:33"]="点击对你的战友表示敬意。"}}
D.SpellTexts[220297]={Description={["0e023eb7b57d7e5c:61"]="向附近敌人发射一颗宝珠，爆炸后会造成奥术伤害。"}}
D.SpellTexts[220324]={Description={["9699e9bcb7bea127:30"]="奥术屏障将你弹了回去。"}}
D.SpellTexts[220360]={Aura={["1649c783dd3499f6:66"]="潜行跟随陶矢进入到日蚀大厅中，寻找马迪亚斯·肖尔。"}}
D.SpellTexts[220366]={Description={["97c7d4b1bd6b356a:40"]="将目标变形为一名冥口战士。 "},Aura={["45df7f2c0b723fdf:28"]="冥口将不会注意到你。"}}
D.SpellTexts[220371]={Description={["c805b6e45e25f389:47"]="发射一枚巨大的火焰投石，造成火焰伤害。"}}
D.SpellTexts[220384]={Description={["9a4f2e65f9ce55da:92"]="风暴幼龙发动俯冲，喷出闪电箭，对其行进路径上的敌人造成自然伤害。"}}
D.SpellTexts[220387]={Description={["4686a1f56d8edfb6:78"]="在施法者周围引起魔法爆炸，对附近所有敌人造成奥术伤害。"}}
D.SpellTexts[220522]={Description={["36902d5a7e93603d:49"]="向敌人扔出一瓶合剂，造成自然伤害。"}}
D.SpellTexts[220403]={Aura={["71a2277eb5a8ea09:19"]="被包裹在邪能之中。"}}
D.SpellTexts[220404]={Aura={["c1bae64cd9d13497:71"]="头痛欲裂，恶心反胃，疲惫不堪。有人玩得太过火了。"}}
D.SpellTexts[220409]={Description={["9b2e6eefcb10174a:113"]="召唤一道触须冒出地面，造成物理伤害，并击退区域内的所有玩家。"}}
D.SpellTexts[220415]={Description={["7f2370b529ffbca8:52"]="对你的目标使用单份剂量的魔蝠毒素解毒剂。"}}
D.SpellTexts[220417]={Description={["d274695164c63eb0:54"]="魔蝠唾液中的毒素会使其撕咬具有化脓腐烂效果。"},Aura={["e0d764b5225b9d66:9"]="被感染。"}}
D.SpellTexts[220422]={Description={["4cbf2fa962d810b2:44"]="发射一枚水泡，对一名敌人造成冰霜伤害。"}}
D.SpellTexts[220426]={Description={["f15c6dd5d2a81112:58"]="猛击地面，对附近所有敌人造成物理伤害。"}}
D.SpellTexts[220436]={Description={["1549f28070c80e93:65"]="哈维尔击打目标，造成物理伤害，并击退他们。"}}
D.SpellTexts[220437]={Description={["5c15a7c4257f868d:60"]="在施法者附近召唤一股潮水，对所有敌人造成冰霜伤害。"}}
D.SpellTexts[220470]={Description={["3848541605f1a757:121"]="施法者卯足全力对当前目标发动攻击，对途中碰到的任意目标造成大量的物理伤害。"}}
D.SpellTexts[220475]={Description={["9da1b5ba847f82ad:83"]="这只熊背上的脓肿每次被攻击时都会破裂，形成毒脓，造成自然伤害。"},Aura={["5305d7d6acc0d383:35"]="受到伤害形成毒脓。"}}
D.SpellTexts[220480]={Aura={["f5382997a68dee6c:20"]="允许骑乘战斗。"}}
D.SpellTexts[220484]={Aura={["f5382997a68dee6c:20"]="允许骑乘战斗。"}}
D.SpellTexts[220486]={Aura={["d2e4d683c0578934:50"]="你让泰姆贾里斯失望了。让时间治愈他受伤的感情吧。"}}
D.SpellTexts[220488]={Aura={["f5382997a68dee6c:20"]="允许骑乘战斗。"}}
D.SpellTexts[220489]={Aura={["f5382997a68dee6c:20"]="允许骑乘战斗。"}}
D.SpellTexts[220490]={Description={["2f16862ae270d6d5:58"]="喷出岩石吐息，对前方的敌人造成自然伤害。"}}
D.SpellTexts[220491]={Aura={["f5382997a68dee6c:20"]="允许骑乘战斗。"}}
D.SpellTexts[220494]={Description={["8e418322ee77e823:80"]="邪能云雾包裹着施法者，对附近的所有敌人造成火焰伤害。"},Aura={["3c3de88c2be8bda5:31"]="对附近的敌人造成火焰伤害。"}}
D.SpellTexts[220495]={Description={["8e418322ee77e823:80"]="邪能云雾包裹着施法者，对附近的所有敌人造成火焰伤害。"},Aura={["01d3549e583d74c9:30"]="对附近的敌人造成火焰伤害"}}
D.SpellTexts[220497]={Description={["343fff6bcb66368e:46"]="敲击战鼓来引诱尤胡塔姆到进食区域。"}}
D.SpellTexts[220499]={Description={["710d25df97c456fa:106"]="召唤或解散一只可供骑乘的黑锋死亡战马，可以在战斗中骑乘。\r\n\r\n只能在破碎群岛和阿古斯使用。"}}
D.SpellTexts[220504]={Aura={["f5382997a68dee6c:20"]="允许骑乘战斗。"}}
D.SpellTexts[220505]={Aura={["f5382997a68dee6c:20"]="允许骑乘战斗。"}}
D.SpellTexts[220506]={Aura={["f5382997a68dee6c:20"]="允许骑乘战斗。"}}
D.SpellTexts[220507]={Aura={["f5382997a68dee6c:20"]="允许骑乘战斗。"}}
D.SpellTexts[220508]={Description={["49fa317f6290a908:101"]="召唤或解散一只可供骑乘的白银之手战马，可以在战斗中骑乘。\r\n\r\n只能在破碎群岛和阿古斯使用。"}}
D.SpellTexts[220510]={Aura={["55b17d0fa2a865d4:31"]="骑乘时倍感舒适。"}}
D.SpellTexts[220511]={Description={["cece0cfd0469075e:29"]="制造一个丝纹鞍具毯子。"}}
D.SpellTexts[220512]={Description={["03bef4356481dfc4:44"]="这个生物生命值很低，需要治疗！"},Aura={["03bef4356481dfc4:44"]="这个生物生命值很低，需要治疗！"}}
D.SpellTexts[220518]={Description={["8bd12a38ced89a87:25"]="切换成圣诞版。"},Aura={["166812c5c371a366:14"]="节日快乐！"}}
D.SpellTexts[220519]={Description={["6e1e620642022be3:25"]="免疫范围伤害。"},Aura={["6e1e620642022be3:25"]="免疫范围伤害。"}}
D.SpellTexts[220530]={Description={["47524693594d7e22:50"]="野蛮地猛击一名敌人，造成物理伤害。 "}}
D.SpellTexts[220534]={Description={["4855ed6a6d02099d:90"]="恶毒地撕扯敌人的血肉，造成物理伤害，并根据造成的伤害恢复生命。"}}
D.SpellTexts[220535]={Description={["654af563ea5d0bda:35"]="使附近所有被投出的合剂获得生命。"}}
D.SpellTexts[220543]={Aura={["1a03c6693857a4ac:12"]="打断。"}}
D.SpellTexts[220574]={Description={["eedc9b103fb9de05:33"]="该地区正在遭受燃烧军团的攻击。"},Aura={["eedc9b103fb9de05:33"]="该地区正在遭受燃烧军团的攻击。"}}
D.SpellTexts[220580]={Aura={["f7b798ca583da6b9:12"]="被击倒。"}}
D.SpellTexts[220583]={Description={["aa764f3b9f58aef8:32"]="对一名敌人造成物理伤害。"}}
D.SpellTexts[220585]={Description={["f348a11eba8be1bd:55"]="向目标发射一支污水箭矢，造成自然伤害。"}}
D.SpellTexts[220595]={Aura={["ac05b072b5e7a223:29"]="满溢着借来的能量。"}}
D.SpellTexts[220599]={Description={["94dd6703cd2cd936:79"]="从包裹中拽出一个枯法者，尝试从他圣体中挤榨参与的生命力。"}}
D.SpellTexts[220604]={Description={["768ffe3c1edff91b:76"]="施法者召唤锯齿水晶飞向目标，造成自然伤害。"}}
D.SpellTexts[220606]={Description={["d3dbf7d88a769623:57"]="玛丽桑德拉从体内排出剧毒软泥来保护自己。"},Aura={["c27df8295d4e82d6:24"]="排出剧毒软泥"}}
D.SpellTexts[220615]={Description={["68aae4adc7ee3156:74"]="制造多次邪能爆破，每次造成火焰伤害并将目标击退。"}}
D.SpellTexts[220627]={Description={["6524d0f44047f66b:98"]="对附近所有敌人造成火焰伤害，击退敌人并造成额外的持续火焰伤害。"}}
D.SpellTexts[220628]={Description={["d3dfdce2e585edd7:60"]="对施法者前方锥形区域内的所有敌人造成物理伤害。"}}
D.SpellTexts[220631]={Description={["297d7df3b7c0e864:92"]="躲在矿石后面，偏转所有远程攻击和法术，并格挡来自前方的所有近战攻击。"},Aura={["70dc7251c401f434:30"]="偏转来自前方的攻击。"}}
D.SpellTexts[220635]={Description={["272ebb9b8abf6ebe:59"]="践踏地面，对附近所有敌人造成物理伤害。"}}
D.SpellTexts[220665]={Description={["b1a3f1dcd17b37a5:111"]="向地面扔出烟雾弹，使你消失在一阵烟雾中。\r\n\r\n只能在破碎群岛和阿古斯使用。"}}
D.SpellTexts[220668]={Description={["6ade3a1761103638:44"]="恢复100点能量。\r\n\r\n只能在破碎群岛使用。"}}
D.SpellTexts[220682]={Aura={["d86312dd54a6efe2:14"]="瘫痪。"}}
D.SpellTexts[220702]={Description={["e48adfcaccdf628d:76"]="苏伊什爆发冲刺，移动速度提高，并践踏脚下的敌人。"}}
D.SpellTexts[220713]={Description={["a76a475683b838c9:150"]="卓格巴尔切割面前的地面，对直线上的所有敌人造成物理伤害。被该攻击命中的敌人会吸引附近的蜥蜴前来争食。"}}
D.SpellTexts[220746]={Description={["0d694fe970c77688:30"]="将你传送至拉文霍德庄园。"}}
D.SpellTexts[220764]={Description={["1fdeb115888e4466:41"]="向一名敌人掷出钩子，将其拖到脚下。"}}
D.SpellTexts[220765]={Description={["2b0c4179a7807b56:38"]="向敌人冲锋，造成奥术伤害。"}}
D.SpellTexts[220767]={Description={["fa78b31f38a112da:33"]="传送到尼斯卡拉的恶魔世界。"}}
D.SpellTexts[220772]={Aura={["76d64388f2e6553f:12"]="无法移动。"}}
D.SpellTexts[220787]={Description={["fa78b31f38a112da:33"]="传送到尼斯卡拉的恶魔世界。"}}
D.SpellTexts[220792]={Description={["ab2f28da7c791a9d:115"]="圣光正在守护你。如果你受到致命伤害，圣光会为你回复全部生命值，并击退周围的敌人。"},Aura={["92483b53d8784efc:52"]="圣光正在守护着你，保护你免受致命伤害。"}}
D.SpellTexts[220803]={Description={["38eea6691924a8e4:57"]="被奥丁选中跻身英灵殿的瓦拉加尔。"},Aura={["38eea6691924a8e4:57"]="被奥丁选中跻身英灵殿的瓦拉加尔。"}}
D.SpellTexts[220831]={Description={["b91732370f11fc40:58"]="施放恶魔变身时会让周围的小动物在恐惧中逃跑。"}}
D.SpellTexts[220841]={Description={["019ac6a4ecbb0a17:57"]="你充满震撼力的造型吓得小动物到处乱跑。"},Aura={["7af7b1767e359139:15"]="因恐惧而逃跑。"}}
D.SpellTexts[220842]={Description={["a12f68d1a203ed94:37"]="受到巫妖王的保护。"},Aura={["dd89b52bc5171b56:69"]="受到巫妖王的保护。每10分钟只会生效一次。"}}
D.SpellTexts[220843]={Aura={["ef8f7a36ede62aa1:35"]="借助圣光的力量而复活。"}}
D.SpellTexts[220856]={Description={["c37453d95f4780b2:31"]="将你自己伪装成一个木头箱子。"},Aura={["f9f2393b3e64106a:29"]="你变成了一个可疑的木头箱子。"}}
D.SpellTexts[220861]={Description={["8bd12a38ced89a87:25"]="切换成圣诞版。"},Aura={["166812c5c371a366:14"]="节日快乐！"}}
D.SpellTexts[220862]={Description={["8bd12a38ced89a87:25"]="切换成圣诞版。"},Aura={["166812c5c371a366:14"]="节日快乐！"}}
D.SpellTexts[220873]={Description={["8bd12a38ced89a87:25"]="切换成圣诞版。"},Aura={["166812c5c371a366:14"]="节日快乐！"}}
D.SpellTexts[220880]={Description={["c43730ca44932fad:29"]="获得释放圣光技能。"},Aura={["c43730ca44932fad:29"]="获得释放圣光技能。"}}
D.SpellTexts[220881]={Description={["253be8f8698d3a73:21"]="释放一阵圣光。"},Aura={["253be8f8698d3a73:21"]="释放一阵圣光。"}}
D.SpellTexts[220887]={Description={["ab2f28da7c791a9d:115"]="圣光正在守护你。如果你受到致命伤害，圣光会为你回复全部生命值，并击退周围的敌人。"},Aura={["dae6bbac12483417:35"]="受到圣光保护，免受致命伤害。"}}
D.SpellTexts[220897]={Description={["37dca13161ce4bdc:72"]="对当前目标造成物理伤害，并会弹射到另外2个额外目标身上。"}}
D.SpellTexts[220903]={Description={["645c050df71280a8:30"]="对目标造成自然伤害。"},Aura={["860a3bef12bd5fa4:37"]="每几秒受到一次自然伤害。"}}
D.SpellTexts[220908]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[220921]={Description={["9b9f46e89d6adfbd:75"]="干扰一颗腐化的龙蛋，使一只怨嗣雏龙破卵而出，并开始进食。"}}
D.SpellTexts[220923]={Description={["8708de87b4e840fe:28"]="随机召唤一个野兽伙伴。"}}
D.SpellTexts[220931]={Aura={["68757908256706a9:38"]="你正在发出奇怪的嘀嗒声。"}}
D.SpellTexts[220933]={Description={["640d790938fc1570:74"]="攻击目标身上的要害，造成物理伤害并降低其急速。"}}
D.SpellTexts[220939]={Description={["e6a10917cb06e24a:96"]="从一位无冕者的私人储物箱中找到一瓶有用的战斗药水将其喝下。\r\n\r\n只能在破碎群岛和阿古斯使用。"}}
D.SpellTexts[220940]={Description={["117e5454691ac925:60"]="在匕首上涂抹毒药，有几率造成自然伤害。"},Aura={["17431aacd136ab5d:29"]="攻击时有几率附加剧毒。"}}
