D.SpellTexts[220984]={Description={["9a94bfdc424afd23:50"]="造成火焰伤害，并留下一小滩邪能粘液。"},Aura={["5a0481eeeadd75cb:49"]="造成火焰伤害，并留下一小滩邪能粘液"}}
