D.SpellTexts[221117]={Aura={["70a0394296a9e2bd:14"]="因恐惧而逃跑。"}}
D.SpellTexts[221122]={Description={["ec086f670e42ae48:44"]="造成火焰伤害，并将敌人击飞到空中。"},Aura={["ec086f670e42ae48:44"]="造成火焰伤害，并将敌人击飞到空中。"}}
D.SpellTexts[221132]={Description={["785862e6c1fc27cf:92"]="将奥术能量注入到目标体内，使其爆炸，对附近玩家造成奥术伤害。"}}
D.SpellTexts[221146]={Description={["f79372206bbc2685:47"]="惊吓区域内的敌人，使其在恐惧中四处逃跑。"}}
D.SpellTexts[221147]={Description={["b36ea54cf8158505:43"]="造成暗影伤害，并对敌人造成恐惧效果。"},Aura={["a228609abb56905f:7"]="恐惧。"}}
D.SpellTexts[221160]={Description={["f5c05896872156bb:31"]="将所有敌人拉向施法者。"}}
D.SpellTexts[221169]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[221170]={Description={["f1b6a9cc79596a61:40"]="强力的一击，让你飞上天空。"},Aura={["c628681fa485f26e:21"]="飞向天空。"}}
D.SpellTexts[221177]={Description={["99e40b91a5a01e38:74"]="用邪能猛击地面，使一条直线上的地面喷发出邪能喷泉。"},Aura={["99e40b91a5a01e38:74"]="用邪能猛击地面，使一条直线上的地面喷发出邪能喷泉。"}}
D.SpellTexts[221186]={Description={["0a123017b86a6d50:25"]="风正在将敌人推开。"},Aura={["0a123017b86a6d50:25"]="风正在将敌人推开。"}}
D.SpellTexts[221196]={Description={["6a2afbd04d10d3b5:47"]="造成暗影伤害，并将目标击飞到空中。"},Aura={["6a2afbd04d10d3b5:47"]="造成暗影伤害，并将目标击飞到空中。"}}
