D.SpellTexts[221204]={Description={["795afd90fce7a89d:30"]="这个单位附近的空气受到了扰动。"},Aura={["795afd90fce7a89d:30"]="这个单位附近的空气受到了扰动。"}}
D.SpellTexts[221206]={Aura={["b1229e5c591a6281:31"]="移除时释放暗影波。"}}
D.SpellTexts[221208]={Description={["31be7987a1fc36e4:103"]="在施法者身边召唤一个强大的暗影化身，将敌人拉向它，并向它脚下的地面下毒。"},Aura={["31be7987a1fc36e4:103"]="在施法者身边召唤一个强大的暗影化身，将敌人拉向它，并向它脚下的地面下毒。"}}
D.SpellTexts[221213]={Description={["219c6afc11e72441:82"]="一个暗影之池环绕着施法者，每秒对站在其中的敌人造成暗影伤害。"},Aura={["f8d70e2a590f3a2d:70"]="被暗影之池所环绕。站在其中的敌人每秒会受到暗影伤害。"}}
D.SpellTexts[221235]={Description={["f3c8fee4a76e42a7:47"]="向目标位置释放一道冲击波。"},Aura={["f3c8fee4a76e42a7:47"]="向目标位置释放一道冲击波。"}}
D.SpellTexts[221243]={Description={["6b917e641260e163:73"]="不停地用劈肉斧猛击前方的地面，造成大量伤害。"},Aura={["9e8531d3b486075a:15"]="缝合大王猛击"}}
D.SpellTexts[221246]={Aura={["dd5f867f83bf3e62:56"]="吸收治疗。\r\n如果光环效果结束，则会造成大量暗影伤害。"}}
D.SpellTexts[221259]={Description={["88ce9b2e1158a50d:59"]="召唤前血色十字军法师提摩莱恩的灵魂。"}}
D.SpellTexts[221260]={Description={["7ab62fcce3bf6199:30"]="将施法者传送到沙尔艾兰。"}}
D.SpellTexts[221282]={Description={["4ab376e4a98a1363:63"]="召唤大法师瓦格斯，将他的智慧赋予你与你的盟友。"}}
D.SpellTexts[221285]={Aura={["cb728af1eaa11488:33"]="每秒受到一次自然伤害。"}}
D.SpellTexts[221287]={Description={["b0bc55204b2fd1d9:39"]="攻击目标，造成冰霜伤害。"}}
D.SpellTexts[221293]={Description={["f68781a57f5ff7a0:53"]="向敌人扔出一个箱子，造成物理伤害。"}}
