D.SpellTexts[221324]={Description={["b822dfab977241ec:68"]="跳向敌人，造成物理伤害，并使附近所有敌人昏迷。"}}
D.SpellTexts[221325]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
