D.SpellTexts[221348]={Description={["20b9ffe5551b9ac0:67"]="向前冲锋，造成物理伤害并将敌人击飞到空中。"}}
D.SpellTexts[221355]={Aura={["cd4c34c8a358fae1:8"]="被嘲讽。"}}
D.SpellTexts[221357]={Description={["0354971edb54951b:77"]="发射榴霰弹，对施法者前方所有敌人造成物理伤害。"}}
D.SpellTexts[221363]={Description={["d8e9b63ed8f16711:89"]="使目标感染毒素，受到破裂效果影响，对附近玩家造成自然伤害。"}}
D.SpellTexts[221377]={Description={["fd8557c36d4eeb48:39"]="召唤几只天灾鼠协助施法者。"}}
D.SpellTexts[221383]={Aura={["615de33e519aaddd:17"]="快速攻击。"}}
D.SpellTexts[221385]={Aura={["a1e6e4cb5b634f40:153"]="迪瑟洛克假扮成马迪亚斯·肖尔，并宣布若在暴风城见到你就格杀勿论。守卫和市民都会攻击你。如果骑上坐骑，你将被屋顶的军情七处狙击手射杀。"}}
D.SpellTexts[221388]={Aura={["10742bc923f4dc4e:42"]="周期性地对敌人造成火焰伤害。"}}
D.SpellTexts[221392]={Description={["0273bdbe436a91c5:101"]="提高熊形态和猎豹形态下的移动速度。\r\n\r\n不会与其他永久性加速效果叠加。"},Aura={["b8d438c11e57ce04:43"]="熊形态和猎豹形态下的移动速度提高了。"}}
D.SpellTexts[221394]={Aura={["39ae90f47a3b893b:27"]="每秒冲击敌人。"}}
D.SpellTexts[221404]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[221411]={Description={["6bea5daa8d239821:52"]="召唤一门幽灵迫击炮，协助召唤者。"}}
D.SpellTexts[221412]={Description={["4e76e64b10807308:56"]="施法者大叫一声，召唤一支青蛙大军来协助他。"}}
D.SpellTexts[221413]={Description={["0273bdbe436a91c5:101"]="提高熊形态和猎豹形态下的移动速度。\r\n\r\n不会与其他永久性加速效果叠加。"},Aura={["b8d438c11e57ce04:43"]="熊形态和猎豹形态下的移动速度提高了。"}}
D.SpellTexts[221415]={Description={["0273bdbe436a91c5:101"]="提高熊形态和猎豹形态下的移动速度。\r\n\r\n不会与其他永久性加速效果叠加。"},Aura={["b8d438c11e57ce04:43"]="熊形态和猎豹形态下的移动速度提高了。"}}
D.SpellTexts[221416]={Description={["0273bdbe436a91c5:101"]="提高熊形态和猎豹形态下的移动速度。\r\n\r\n不会与其他永久性加速效果叠加。"},Aura={["b8d438c11e57ce04:43"]="熊形态和猎豹形态下的移动速度提高了。"}}
D.SpellTexts[221418]={Aura={["ac8aaf256df837c4:24"]="对周围的所有敌人造成伤害。"}}
D.SpellTexts[221420]={Description={["16faa4683018f7f7:21"]="在沙拉尼尔外面着陆。"}}
D.SpellTexts[221421]={Description={["b79748db309ff740:38"]="对附近的所有敌人造成物理伤害。"}}
D.SpellTexts[221427]={Aura={["8cf7e928a48ab8fd:27"]="听奥丁讲述故事。"}}
D.SpellTexts[221433]={Description={["38034938b3dd71f1:58"]="发射榴霰弹，对施法者前方所有敌人造成物理伤害。"}}
D.SpellTexts[221439]={Description={["097f54c8c3a160e5:93"]="所有存活的邪能魔灵会分裂成两个，制造出一个和其剩下生命值相同的复制体。"}}
D.SpellTexts[221442]={Description={["ee3f0a44712f5dd7:41"]="发射幽灵般的迫击炮弹，造成火焰伤害。"}}
D.SpellTexts[221443]={Aura={["76d64388f2e6553f:12"]="无法移动。"}}
D.SpellTexts[221446]={Description={["45a501e91c9b57fe:34"]="对敌人造成极高的冰霜伤害。"}}
D.SpellTexts[221483]={Aura={["077fb8bd55ac102a:107"]="呆在干草包中时，你会处于隐藏状态，免受伤害。当你离开后，你会受到保护，持续一小段时间。"}}
D.SpellTexts[221484]={Aura={["6231abd5d906a4d4:37"]="你可以在短时间内免受伤害。"}}
D.SpellTexts[221485]={Description={["4284b3f51af68ea0:257"]="施法者将精神集中在施法上。任何直接的挑战都会使他们向挑战者的位置移动，否则施法者会站在原地不动，专注施法。\r\n打断该生物或其生命值低于90%时，它会开始攻击所有敌人。"},Aura={["b6601705d9cb2ba8:133"]="嘲讽此生物会使其向你的位置移动。\r\n打断此生物或其生命值低于90%时，它会开始攻击所有敌人。"}}
D.SpellTexts[221486]={Description={["21ae6c61cf23e8b6:99"]="达到最大生命值时会被净化，立即杀死所有玩家，并对所有敌人施放恶魔之灾。"}}
D.SpellTexts[221487]={Aura={["fd0499640e30b2d5:47"]="在视野范围内落下星辰。"}}
D.SpellTexts[221488]={Description={["913df132e825ade9:14"]="星辰召唤"}}
D.SpellTexts[221497]={Description={["668ba61c1ac97c91:32"]="梵妮莎·范克里夫与你并肩作战。"}}
D.SpellTexts[221511]={Description={["b219232eed691aef:67"]="对一个敌人造成奥术伤害，将其向施法者的方向拉近。"}}
D.SpellTexts[221512]={Description={["6445a6056ae4060e:14"]="突刺目标。"}}
D.SpellTexts[221518]={Description={["167d0faf64e9bbd8:66"]="征调一队瓦拉加尔候选者，陪伴你的勇士执行任务。"}}
D.SpellTexts[221521]={Description={["806921b5d7954860:69"]="施法者在一个友方目标身上施放一个护盾，保护其免受伤害。"}}
D.SpellTexts[221524]={Description={["806921b5d7954860:69"]="施法者在一个友方目标身上施放一个护盾，保护其免受伤害。"}}
D.SpellTexts[221525]={Description={["816d96581257a6a3:47"]="将敌人拉向你，使其短暂昏迷。"}}
D.SpellTexts[221527]={Aura={["3f31ea87b49b26e0:39"]="被放逐。\r\n免疫伤害。\r\n无法被治疗。"},Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[221542]={Aura={["0e7c76f3a3ae5b20:54"]="该光环施法者所受到的伤害会转移到你身上。"}}
D.SpellTexts[221553]={Description={["d626887a7b03bbf3:50"]="制造一道屏障，使施法者免疫一切攻击。"},Aura={["9c9b4d7eae52d7eb:7"]="免疫。"}}
D.SpellTexts[221556]={Description={["837c41935f9075be:54"]="休眠的魔灵会作为邪能魔灵再次出现。"}}
D.SpellTexts[221557]={Description={["d310a7d784f1abb2:67"]="召唤一个冰霜巨龙，立刻完成你地图上的一个非精英类世界任务。"}}
D.SpellTexts[221560]={Description={["88a982ded42dd757:26"]="激活附近的构造体。"}}
D.SpellTexts[221561]={Description={["e09e8d8120465f98:98"]="释放邪能之槌的怒火，发射裂隙火炮，立刻完成你地图上的一个非精英类世界任务。"}}
D.SpellTexts[221573]={Description={["549653e29c370cab:44"]="受到伤害会生成法力值。\r\n\r\n法力值满时效果取消。"},Aura={["549653e29c370cab:44"]="受到伤害会生成法力值。\r\n\r\n法力值满时效果取消。"}}
D.SpellTexts[221579]={Description={["d88475abc69baaea:72"]="炽热的刀刃在施法者周围旋转，对附近所有敌人造成火焰伤害。"}}
D.SpellTexts[221582]={Description={["6c0f47a76b595242:14"]="正在操作"}}
D.SpellTexts[221584]={Aura={["fd0499640e30b2d5:47"]="在视野范围内落下星辰。"}}
D.SpellTexts[221585]={Description={["767c9571ee65918e:63"]="借助风的力量腾空而起。只能在破碎群岛使用。"}}
D.SpellTexts[221587]={Description={["fe178260721e4041:80"]="命令白银之手先锋立刻完成你地图上的一个非精英类世界任务。"}}
D.SpellTexts[221589]={Description={["4eb073a6835200a3:133"]="此生物会极度专注于仪式行为。嘲讽这个生物或其生命值低于90%时，它会开始攻击所有敌人。"},Aura={["4eb073a6835200a3:133"]="此生物会极度专注于仪式行为。嘲讽这个生物或其生命值低于90%时，它会开始攻击所有敌人。"}}
D.SpellTexts[221597]={Description={["7987be3fff205916:73"]="释放雷神之力，立刻完成你地图上的一个非精英类世界任务。"}}
D.SpellTexts[221602]={Description={["bebab717ef8d0406:73"]="释放达拉然之力，立刻完成你地图上的一个非精英类世界任务。"}}
D.SpellTexts[221615]={Description={["9744f972e8b7da7d:64"]="在破碎群岛的户外区域，提高你脱离战斗后的恢复速度。"}}
D.SpellTexts[221622]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[221626]={Description={["9c76da1fb365f63a:32"]="守备官波鲁斯与你并肩作战。"}}
D.SpellTexts[221629]={Aura={["1b25fe9b48de21c0:14"]="喷水！"}}
