D.SpellTexts[221777]={Description={["09767e82cae39cc9:232"]="开始书写你的传奇。击杀一名等级为113的敌人会在书上多写一行。受过铭文训练的玩家书写速度为原本的四倍。\r\n\r\n写完一本书后，可以卖给任何一名商人，或者到达拉然下水道交换盲目之眼。"}}
D.SpellTexts[221778]={Description={["6ab0f5824a606645:165"]="没有任何潜行者的潜行技巧能像陶矢那样完美。如果不想被人看到，就没有任何人能看到她。正是这样的能力让她的刺杀更为致命，因为敌人几乎无法防御她从背后的偷袭。"},Aura={["74f8245cd3f5ea57:86"]="陶矢掌握了敏锐潜行者之道。她是一名极为优秀的战略家和卓越的外交家。"}}
D.SpellTexts[221779]={Description={["90a695f21131931b:176"]="马迪亚斯·肖尔大师是联盟里间谍活动的核心人物。在情报和战略方面的一切事物上，他都为国王提供建议。他已经同意，只要你是无冕者的代表，就可以达成一个私下的联盟。"},Aura={["68ee29f4440ff9e3:89"]="马迪亚斯·肖尔掌握了刺杀潜行者之道。他是军情七处的领袖，也是极为有价值的盟友。"}}
