D.SpellTexts[223372]={Description={["79568d1bb1ea9ef2:87"]="不断暴露在生命精华中会放大沙兰使用虚空之触的能力。该效果会叠加。"}}
D.SpellTexts[223395]={Description={["05bd40a64f70712b:61"]="释放出邪能新星，对所有敌人造成火焰伤害。"}}
D.SpellTexts[223396]={Description={["839e953d7d1aafd4:18"]="踢走一只鹿角小飞兔。"}}
D.SpellTexts[223413]={Description={["3549aab575afaafe:36"]="可以进入传送中枢。"}}
D.SpellTexts[223420]={Description={["ac275380dee97dc3:109"]="朝着指定玩家的方向猛砸地面，对直线上的所有玩家造成物理伤害并击退他们。"}}
D.SpellTexts[223444]={Description={["f7cdb0d894a3a8e9:155"]="在地上设置信标，返回沙尔艾兰。信标采用了尖端传送技术，可以覆盖苏拉玛85%以上的区域，只需要20小时充电！"}}
D.SpellTexts[223446]={Description={["554d03dc30f0b78d:35"]="制作一个“自制的”夜之子宴会面具。"},Aura={["6271e826e2fe0bf5:67"]="你也许没法混进贵族的交际圈，但可以举办自己的宴会！"}}
D.SpellTexts[223473]={Description={["c864cf2b7f195716:139"]="剪切一名敌人，造成物理伤害，并有很小的几率从目标身上剥离一块小型灵魂残片，消耗时可以恢复大量生命。"},Aura={["c864cf2b7f195716:139"]="剪切一名敌人，造成物理伤害，并有很小的几率从目标身上剥离一块小型灵魂残片，消耗时可以恢复大量生命。"}}
D.SpellTexts[223475]={Description={["82bc9625a318d7c8:25"]="向阵亡的族长致敬。"}}
D.SpellTexts[223488]={Aura={["91aa8c1907a2d1bc:18"]="减缓坠落速度。"}}
D.SpellTexts[223493]={Description={["f53aa6212ed6947a:97"]="在施法者脚下召唤一个落风图腾，让附近的盟友坠落速度减缓。\r\n只能在至高岭使用。"}}
D.SpellTexts[223497]={Description={["81f27ca19efc3cfa:34"]="在你的背上装备一个天角战争甲胄。"},Aura={["cdfbdd8d3b0992c0:26"]="正穿着天角战争甲胄。"}}
D.SpellTexts[223498]={Description={["41c51d7cc93ae7c7:36"]="在你的背上装备一个河鬃战争甲胄。"},Aura={["ac9eb6e8987f778d:28"]="正穿着河鬃战争甲胄。"}}
D.SpellTexts[223499]={Description={["abfea22cae2fb675:37"]="在你的背上装备一个鲜血图腾战争甲胄。"},Aura={["e1b060b8663ab461:29"]="正穿着鲜血图腾战争甲胄。"}}
D.SpellTexts[223500]={Description={["ebbb8c1ed446486d:39"]="在你的背上装备一个至高岭战争甲胄。"},Aura={["28f3426af85848d9:31"]="正穿着至高岭战争甲胄。"}}
D.SpellTexts[223501]={Description={["dcb3d4d117fc8d70:26"]="你正控制着大老爸。"},Aura={["dcb3d4d117fc8d70:26"]="你正控制着大老爸。"}}
D.SpellTexts[223507]={Description={["c46a8dcf3363e8e2:74"]="从施法者脚下召唤一个蛮拳雕像，猛地将其弹射到空中。"}}
D.SpellTexts[223509]={Description={["2c545e166c01c207:14"]="和一个小精灵绑定。"},Aura={["fb69fcbfc9ba1c46:16"]="已和一个小精灵绑定。"}}
D.SpellTexts[223511]={Description={["0664a7d3fe208078:76"]="软泥怪锁定了一个随机敌人，会一直追逐对方，并留下一串灼热软泥水洼。"},Aura={["4f98b1d8393d0727:8"]="被锁定。"}}
D.SpellTexts[223521]={Description={["736ae61901a43f12:58"]="发射一道暗影波浪。触碰到波浪会受到暗影伤害。"}}
D.SpellTexts[223543]={Aura={["193c856d7f46ec2e:95"]="菲娜·伯恩多提尔有时会来帮助你战斗，嘲讽附近所有敌人并反击。"}}
D.SpellTexts[223549]={Description={["0b42d6b529d142ce:42"]="向附近的一艘游船投掷一团魔力之火。"}}
D.SpellTexts[223567]={Description={["3c36808e9575f373:85"]="召唤装满小鬼的流星对附近的敌人造成暗影伤害并召唤数个小鬼。"}}
D.SpellTexts[223578]={Description={["7178cfbd0ed758a4:44"]="召唤或解散一只可供骑乘的勇猛的作战雷象。"}}
D.SpellTexts[223581]={Description={["a833ee6e72013245:31"]="在你附近生长一只蘑菇。"}}
D.SpellTexts[223592]={Aura={["991b84552ee67c34:32"]="反击所有近战攻击。"}}
D.SpellTexts[223594]={Description={["16899e9b5e2682ea:75"]="从施法者脚下召唤一个蛮拳雕像，猛地将其弹射到空中。"}}
D.SpellTexts[223599]={Description={["617c045836f46ddf:76"]="有邪恶的魔法在作祟，体型大幅度缩小且伤害大幅度降低。"}}
D.SpellTexts[223601]={Description={["f8a59706ff750dbd:48"]="软泥死亡时将会爆裂，留下一个软泥怪之池。"}}
D.SpellTexts[223632]={Aura={["c73b5dc517f12860:28"]="这里充满了邪恶的魔法。"}}
D.SpellTexts[223639]={Description={["8e1bfd567053481d:57"]="召唤一个小型的邪能散播器，散播军团的污染物。"}}
D.SpellTexts[223653]={Aura={["3cd8abfa7bfa1755:20"]="效果结束时爆炸。"}}
D.SpellTexts[223655]={Description={["6511f56265e71897:56"]="随机注视一个敌人并吸收沿途任何目标。"},Aura={["4f98b1d8393d0727:8"]="被锁定。"}}
D.SpellTexts[223665]={Description={["e8642e811a1c716c:72"]="戴上这些拉风无比的间谍眼镜来追踪安玻·吉尔妮的血迹。"},Aura={["35694c82b06eb841:12"]="看上去不错！"}}
D.SpellTexts[223666]={Description={["5bb493770d14b54e:79"]="击碎每个玩家脚下的大地，对他们造成火焰伤害并把他们击飞至空中。"}}
D.SpellTexts[223678]={Description={["d5eafd838cd6c178:67"]="召唤来自阿古斯的礼物，命中时对区域范围造成火焰伤害。"},Aura={["bcc33512f7bba5ef:11"]="邪能如雨。"}}
D.SpellTexts[223689]={Aura={["66c77062df42fb71:34"]="向附近敌人脉冲奥术伤害。"}}
D.SpellTexts[223693]={Aura={["70a0394296a9e2bd:14"]="因恐惧而逃跑。"}}
D.SpellTexts[223715]={Description={["98714cc1f1d0132e:61"]="吸取不稳定的法力碎片中的能量，创造一个自身的复制体。"}}
D.SpellTexts[223740]={Description={["0c701f1380fe1060:120"]="你的枯法者部队的伤害提高25%。\r\n\r\n此为永久性效果，将在你下次进入大陷坑场景战役时生效。"}}
D.SpellTexts[223753]={Description={["003199bd9b5ca138:54"]="为你历经战火的神器解锁一种新的配色。"},Aura={["003199bd9b5ca138:54"]="为你历经战火的神器解锁一种新的配色。"}}
D.SpellTexts[223754]={Description={["003199bd9b5ca138:54"]="为你历经战火的神器解锁一种新的配色。"},Aura={["003199bd9b5ca138:54"]="为你历经战火的神器解锁一种新的配色。"}}
D.SpellTexts[223755]={Description={["003199bd9b5ca138:54"]="为你历经战火的神器解锁一种新的配色。"},Aura={["003199bd9b5ca138:54"]="为你历经战火的神器解锁一种新的配色。"}}
D.SpellTexts[223761]={Description={["308dff9cea0083fd:15"]="提高伤害。"}}
D.SpellTexts[223762]={Description={["6cf8aef3727e1170:15"]="提高生命值。"}}
D.SpellTexts[223766]={Description={["d23026bc310b5671:28"]="将你的枯法者派往沙尔艾兰。"},Aura={["d23026bc310b5671:28"]="将你的枯法者派往沙尔艾兰。"}}
D.SpellTexts[223769]={Description={["4a4196a48f4d6bb5:57"]="对一名敌人投掷大便，造成物理伤害和心理创伤。"}}
D.SpellTexts[223799]={Description={["645c050df71280a8:30"]="对一名敌人造成自然伤害。"}}
D.SpellTexts[223802]={Description={["1778e20f211e0986:54"]="一股黑暗之力愿用力量来换取你的效忠。"},Aura={["f4216d80e4b45e57:50"]="脑海中回响着黑暗的声音……\r\n\r\n右键点击取消这些声音。"}}
D.SpellTexts[223805]={Description={["9c75bd9ecebe1fdd:48"]="传送至破碎群岛中的一个调和的魔网结点。"}}
D.SpellTexts[223814]={Description={["223bf9628fa73a37:142"]="骑乘机械化木材采集器，可以以很快的速度飞行。它的爪子非常精巧，草药学家可以用来采集药草！这是一种飞行坐骑。"}}
D.SpellTexts[223819]={Aura={["ecc2bd426e83b259:53"]="下一个消耗神圣能量的技能变为免费。"}}
D.SpellTexts[223826]={Description={["a3b7c9331faafe66:60"]="安抚目标区域内最多3个枯法单位，并将他们送往沙尔艾兰。"},Aura={["0920bd299ace7dc8:8"]="被抚慰。"}}
D.SpellTexts[223829]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[223838]={Description={["26bf97852d7a975c:23"]="将你传送至卡拉赞。"}}
D.SpellTexts[223839]={Description={["9957bdec2af7db0f:19"]="召唤你的玩具石。"}}
D.SpellTexts[223844]={Description={["d1edede9d540b454:205"]="占星师使用这个手持装置将大量星光聚焦在一小块区域。这个装置主要在节庆和拜星仪式期间使用，也会用于占星师拿不到书架顶部物品的时候。"}}
D.SpellTexts[223846]={Description={["32680ac7067d50e6:149"]="苏拉玛当权的王子和公主喜欢只在出席最正式的场合时戴上王冠。其他时候这些王冠都被锁了起来，形态并不时髦。"}}
D.SpellTexts[223848]={Description={["1979436a2c00cc65:226"]="黑鸦堡垒由一批仆从驻守维护，其中一人名为卡林达斯，负责看管堡垒的军械辎重。和大多数拉文凯斯的追随者一样，他在上古之战中败给了恶魔大军。"}}
D.SpellTexts[223849]={Description={["a0af99334300bea8:114"]="这个无比强大的上层精灵法术核心在一次鲁莽的考古勘测中弄碎，现在只剩下这些碎片。"}}
D.SpellTexts[223850]={Description={["0c3d36712faefbb8:118"]="这把钥匙无法打开任何一扇门，但它象征着学院的邀请，仿佛在说“我们的大门为你敞开。”"}}
D.SpellTexts[223851]={Description={["cca283ca1290fa7f:181"]="受到广大矿工和铁匠拥戴的瑞苏·铁角是第一批来到破碎群岛的牛头人拓荒者之一，他的后裔在至高岭顶峰附近的铁角飞地延续了他善于打磨金属的传统。"}}
D.SpellTexts[223852]={Description={["05fa1f9e6fcc9c8b:157"]="卓格巴尔向来是珠宝加工的大师。具体来说，原始部落的萨满祭司会佩戴由三颗石头制成的沉重项链，而这些项链由一代代师父传给他们的徒弟。"}}
D.SpellTexts[223853]={Description={["a2286b5a57530d13:95"]="艾特洛是上古之战传奇英雄胡恩·高岭的宠物、坐骑和战斗伙伴。"}}
D.SpellTexts[223854]={Description={["f796c43720e4533e:183"]="强大恶魔的眼睛，保存在风暴峡湾的冰冷石头地面中。根据上古之战时期的文献记载，邪能领主统帅乌达维斯的目标是消灭艾泽拉斯所有的生命。"}}
D.SpellTexts[223855]={Description={["fb8b4632feb863f7:178"]="在并不甘愿合作的莫尔葛工程师的指引下，恶魔猎手创造出了许多这样的传送门前往马顿。不幸的是，他们对这些传送门疏于管范，致使从传送门中前来的恶魔比过去的多得多。"}}
D.SpellTexts[223856]={Description={["9ea19fbf8a0200f8:170"]="许多鲁莽的冒险者在不知道这些装置有什么功能的情况下启动了它们，从而不幸被夺去性命。没有人清楚开启这些装置会召唤一个小鬼，还是一整支深渊领主军队。"}}
D.SpellTexts[223857]={Description={["6aec7a9bdfaa7c84:119"]="时至今日人们仍然不明白，为什么有些生物，不管是恶魔还是艾泽拉斯的居民，会选择将玛诺洛斯的血放在罐子里来加入他的邪恶阵营。"}}
D.SpellTexts[223858]={Description={["2deba72a872825f1:125"]="匆忙中，德莱尼人离开阿古斯过程中只带走了少许几件神器。这本书籍是保存至今日的少数遗物之一。"}}
D.SpellTexts[223869]={Description={["057cbdefa9538020:56"]="对一名敌人发射水晶飞弹，造成奥术伤害。"}}
D.SpellTexts[223874]={Description={["13cc9b6ff40d1b34:85"]="呼叫希尔乐、洛林和塞莱莎从阴影中现身攻击莱蕾丝的刺杀目标。"}}
D.SpellTexts[223892]={Aura={["8d1ba516913f0449:10"]="正在转化……"}}
D.SpellTexts[223894]={Aura={["d4174d4ba1a3440a:11"]="歇斯底里。"}}
D.SpellTexts[223896]={Aura={["785be2184a7b4481:10"]="隐形。"}}
D.SpellTexts[223898]={Aura={["da517009b2e886fa:21"]="为军团而战。"}}
D.SpellTexts[223901]={Description={["29e389700bb1b6d5:24"]="伪装成目标的样子。"}}
D.SpellTexts[223911]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[223914]={Aura={["70a0394296a9e2bd:14"]="因恐惧而逃跑。"}}
D.SpellTexts[223915]={Description={["69717a9c9ed5f919:47"]="意志脆弱，治疗、伤害和生命值降低。"}}
D.SpellTexts[223922]={Description={["58d9143b82fa356c:70"]="举行致命的仪式，随机召唤一只恶魔。需要至少3名参与者。"}}
D.SpellTexts[223934]={Description={["f2e5f463e9e83aae:17"]="出什么事了？"},Aura={["f2e5f463e9e83aae:17"]="出什么事了？"}}
D.SpellTexts[223935]={Aura={["92ca563f1842318e:33"]="你看上去像是军团的盟友。"}}
D.SpellTexts[223937]={Description={["c459d31a3c59e39f:68"]="在你的音波增幅器中添加音乐“部落之歌”。"}}
D.SpellTexts[223938]={Description={["a4deea21afb4438a:71"]="在你的音波增幅器中添加音乐“联盟之歌”。"}}
D.SpellTexts[223940]={Description={["d555b32577e57212:28"]="制作一个部落之歌的卷轴。"}}
D.SpellTexts[223941]={Description={["c9b146f12e0c890a:29"]="制作一个军团之歌的卷轴。"}}
D.SpellTexts[223948]={Description={["7dff40671c0f687c:68"]="对施法者面前锥形区域内的目标造成物理伤害并击退他们。"}}
D.SpellTexts[223952]={Description={["c4727c1431f5873b:21"]="造成暗影伤害。"}}
D.SpellTexts[223957]={Description={["9d730da8f752318d:34"]="对附近目标造成神圣伤害。"}}
D.SpellTexts[223958]={Aura={["6e8d769db0e52442:17"]="你淤泥缠身！"}}
D.SpellTexts[223963]={Description={["7d03d2b6ac2dabd9:55"]="对锥形范围内的所有目标造成自然伤害并击退他们。"}}
D.SpellTexts[223968]={Description={["f1f5ba6b67424bde:40"]="受害者在水中留下来一串血迹。"},Aura={["53f61b7a4b3f1d13:25"]="你被鲨鱼咬了！"}}
D.SpellTexts[223974]={Aura={["a7a24bcdf384631a:49"]="行走在黑锋骑士团的领地中。"}}
D.SpellTexts[223985]={Description={["cb5d0131e7be24a2:47"]="大幅度提高玩家的经验值。"}}
D.SpellTexts[224026]={Aura={["40792bd097a6e88d:14"]="正在审问。"}}
D.SpellTexts[224039]={Description={["3297f142f8364767:80"]="引导充满致命能量的光线，对施法者面前的目标造成大量奥术伤害。"}}
D.SpellTexts[224042]={Description={["a56beb3c073bb275:49"]="攻击对附近的敌人造成额外的火焰伤害。"},Aura={["a56beb3c073bb275:49"]="攻击对附近的敌人造成额外的火焰伤害。"}}
D.SpellTexts[224047]={Aura={["e0bc0ec08ed2ad29:60"]="在破碎群岛时，攻击时有几率造成火焰伤害。"}}
D.SpellTexts[224053]={Description={["f66e36fc2c6c7501:90"]="制造一个真空区域，把附近的敌人吸入并对他们造成暗影伤害。"}}
D.SpellTexts[224055]={Description={["84ae563ef9f7fcd5:36"]="对附近的敌人造成暗影伤害。"}}
D.SpellTexts[224057]={Description={["e8bde185dab1e8bc:24"]="根据所造成伤害恢复生命值。"},Aura={["e8bde185dab1e8bc:24"]="根据所造成伤害恢复生命值。"}}
D.SpellTexts[224063]={Aura={["93549e0f584afe94:8"]="正在拾取。"}}
D.SpellTexts[224067]={Description={["879c48024075f05f:78"]="鲜血不断从地面喷发出来，沿一条直线向随机目标移动。"}}
D.SpellTexts[224074]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[224083]={Description={["ef2369f71808d4f0:31"]="杀虫行动已开始。"},Aura={["ef2369f71808d4f0:31"]="杀虫行动已开始。"}}
D.SpellTexts[224091]={Description={["7b48d29b791e7070:20"]="移动造成睡眠。"},Aura={["7b48d29b791e7070:20"]="移动造成睡眠。"}}
D.SpellTexts[224112]={Description={["bde92eb050cf26e3:70"]="使灵魂返回身体，让一个死亡的目标复生。可以在战斗中施放。"}}
D.SpellTexts[224113]={Description={["dd4a05f82ae5fef7:22"]="诸灵在烹饪过程中伴随着你，伙计。"},Aura={["dd4a05f82ae5fef7:22"]="诸灵在烹饪过程中伴随着你，伙计。"}}
D.SpellTexts[224122]={Description={["2ecb523dbedbaf16:28"]="你的旅行形态现在看上去像一只雌性的驯鹿。"}}
