D.SpellTexts[225020]={Description={["c8dc74dc6b1c93a3:62"]="由艾格文设计的水晶，专门用于克制艾露尼斯的魔法。\r\n"},Aura={["c8dc74dc6b1c93a3:62"]="由艾格文设计的水晶，专门用于克制艾露尼斯的魔法。"}}
D.SpellTexts[225021]={Description={["396c2a82ccc90fc7:78"]="这副魔法眼镜可以为世界清除蜘蛛天灾，至少可以清除一部分。"},Aura={["c0480c47001f6cb4:24"]="蜘蛛去哪了？"}}
D.SpellTexts[225022]={Description={["f025b116bbfc4ae7:25"]="开启自动虫子清理功能。"}}
D.SpellTexts[225023]={Description={["03cd07a4271b5617:104"]="放置一个梅特里古卷，安抚狂暴的奥术魔法并让奥术生物更加服从你的意志。"}}
D.SpellTexts[225056]={Aura={["1640b623b416d6ae:43"]="阿基萨姆，敬畏臂甲无法触发。"}}
D.SpellTexts[225061]={Description={["6eae006cf4e7acbf:178"]="马林·诺格弗格可能是世上最伟大的炼金专家。虽然身体不够强壮，但机智的大脑弥补了一切。绝对不要低估地精的才华……以及贪婪！"},Aura={["46eafd90fcba276b:71"]="马林·诺格弗格是手段多样的狂徒潜行者。"}}
D.SpellTexts[225077]={Description={["1709278566584a48:165"]="舰队上将特塞斯也许是个卑鄙的海盗，但他也是无尽之海上最强大的决斗者之一。他现在是臭名昭著的藏宝海湾血帆海盗中的舰队上将。"},Aura={["5f1c3992933eb1e9:67"]="舰队上将特塞斯是一位令人恐惧的法外狂徒，他的决斗水平令人称道。"}}
D.SpellTexts[225080]={Description={["19245340d83114df:29"]="这名玩家可以重生。"},Aura={["19245340d83114df:29"]="这名玩家可以重生。"}}
D.SpellTexts[225084]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
