D.SpellTexts[225088]={Description={["5a51b5a12f8b663e:131"]="拉文霍德公爵是有史以来最具传奇色彩的潜行者之一。数十年来，他训练了无数强大的潜行者，教会他们用微妙的手段转移他人注意力的技艺。"},Aura={["744d2c54626617bf:89"]="拉文霍德公爵是一名狡诈的潜行者，他的潜行和转移注意力的水平出神入化，在合适的时机给予敌人致命一击。"}}
D.SpellTexts[225091]={Description={["9da8d7a8ada19d93:60"]="快速旋转，从宝剑中射出充盈着奥术能量的箭矢。"}}
