D.SpellTexts[225228]={Description={["bfcf33e34e2a9002:130"]="发射大量火箭，攻击面前的一切，经常无法命中目标，偶尔也能打中，对击中或未击中的东西都有可能造成火焰伤害。"}}
D.SpellTexts[225258]={Description={["4507e97dafa7b244:65"]="邪火从地面喷发而出，对区域内的迪恩造成火焰伤害。"}}
D.SpellTexts[225290]={Description={["0d2c4187ec52be2e:71"]="吐出锥形火焰，对施法者面前所有敌人造成火焰伤害。"}}
