D.SpellTexts[225575]={Description={["640d6a636c141dee:153"]="萨萨里安的忠诚在黑锋骑士团中无人可及。他毫不动摇的决心和战斗中展现出的技巧赢得了骑士团上下的一致尊敬。"},Aura={["28629b3e7f763aaf:91"]="萨萨里安是一名双持符文剑的冰霜死亡骑士，他可以使用冰霜的力量消灭敌人。"}}
D.SpellTexts[225577]={Description={["09f0c54ea6465b63:138"]="纳兹戈林生前曾是部落最伟大的将领之一。死后，他成为了黑锋骑士团的强大勇士。无论是死是活，很少有人可以和他的勇猛相提并论。"},Aura={["be86b7e00f9bdeaf:84"]="纳兹戈林是一名邪恶死亡骑士，他使用死灵和腐化的力量杀戮敌人。"}}
D.SpellTexts[225580]={Description={["1704de28ecf8b675:143"]="在黑锋骑士团内部，几乎没有其他死亡骑士的速度和敏捷可以和库尔迪拉·织亡者相提并论。他挥舞符文剑作战的技巧早已出神入化。"},Aura={["d4b312a65d7ea2d3:96"]="库尔迪拉·织亡者是一名强大的鲜血死亡骑士，他使用吸血鬼强化的亡灵之力来保护他的盟友。"}}
D.SpellTexts[225583]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[225587]={Description={["fee15ea4c18bb119:150"]="在所有历史记载中，很少有战士像索拉斯·托尔贝恩国王这般具有传奇色彩。作为国王，他广受爱戴。而作为天启四骑士，他将带来恐惧。"},Aura={["d5119361b476ede0:108"]="索拉斯·托尔贝恩是一名强大的冰霜死亡骑士，他使用冰冷无情的亡灵寒冬之力湮灭敌人。"}}
D.SpellTexts[225591]={Description={["ad91471dadad7e22:41"]="你感觉自己必须攻击这个目标……"},Aura={["ad91471dadad7e22:41"]="你感觉自己必须攻击这个目标……"}}
