D.SpellTexts[225683]={Description={["bd1549c65175a2e9:82"]="当你的苦修对一名敌人造成伤害时，同时会为所有受到你的真言术：障影响的盟友恢复生命。"}}
D.SpellTexts[225687]={Description={["ff03573c3c31ec1f:26"]="你拾取了一个鱼人毛绒玩具！"}}
D.SpellTexts[225688]={Description={["ebac28c9ce5c50dc:74"]="动物园不为任何掉在地上遗失的商品负责。"}}
D.SpellTexts[225692]={Description={["153ade53dac45652:191"]="大检察官怀特迈恩生前是一名狂热追随圣光的女祭司，最终走火入魔。死亡让她得以从疯狂中解脱，现在的她是一位无情的、渴求复仇的死亡骑士。"},Aura={["49f643bd978877d6:92"]="大检察官怀特迈恩是一名邪恶死亡骑士，他无情地掌控着瘟疫和不死的力量。"}}
D.SpellTexts[225938]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[225701]={Description={["11431b102e1fe35d:220"]="这只憎恶是首席巫妖克尔苏加德最为实用的造物。有什么比一只忠心无比又急于吞噬敌人的巨大畸形怪物更有用呢？作为憎恶，腐肠是完美的样本。"},Aura={["3a51520344e2cbae:72"]="腐肠是一名鲜血死亡骑士，他是“肉盾”这个词的完美体现。"}}
D.SpellTexts[225703]={Description={["c8d59561dc4dfd72:151"]="阿曼萨加德曾经是一名强大的冰霜法师，与巫妖王的部队奋勇作战。阿尔萨斯被这名法师的力量打动了，让他作为巫妖重生加入亡灵部队。"},Aura={["fe86d7143acc6cd7:74"]="阿曼萨加德使用亡灵的冰霜力量，摧垮所有胆敢反抗他的人。"}}
D.SpellTexts[225705]={Description={["7d38ca45dcd959e0:194"]="大领主达里安·莫格莱尼曾经是黑锋骑士团的领袖，他是有史以来最强大的死亡骑士之一。现在他带领着天启四骑士对抗着燃烧军团，为敌人带去死亡与毁灭。"},Aura={["3f4aaabdbac7e070:99"]="大领主达里安·莫格莱尼是一名邪恶死亡骑士，他使用死亡和腐化的力量来消灭敌人。"}}
D.SpellTexts[225708]={Aura={["b6721196f26ad37b:20"]="你已受到召唤。"}}
D.SpellTexts[225728]={Description={["a82a45c55799934e:57"]="激活守望者猫头鹰雕像来获得其真正的力量。"}}
D.SpellTexts[225740]={Description={["21679352f008787d:40"]="允许一个地面宠物小伙伴和你一起飞翔。"},Aura={["9d561fed5fc20828:23"]="可以和主人一起飞翔。"}}
D.SpellTexts[225741]={Description={["21679352f008787d:40"]="允许一个地面宠物小伙伴和你一起飞翔。"},Aura={["9d561fed5fc20828:23"]="可以和主人一起飞翔。"}}
