D.SpellTexts[225826]={Description={["40ba95ecc6dbeebb:57"]="将那道曾经强烈的奥能光线集中到你面前的目标身上。"},Aura={["79191f60a8b227e7:81"]="经历了漫长的岁月，这道光束已经失去了它的力量，只余下微弱的魔法环绕在你周围。"}}
