D.SpellTexts[228001]={Description={["df475eb595c066e0:81"]="扔出大把大把的硬币，对落地处周围的所有敌人造成神圣伤害。"}}
D.SpellTexts[228049]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[228050]={Aura={["a37b4beb88302194:28"]="免疫所有攻击和法术。"},Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[228058]={Aura={["3275189cfac8a611:48"]="每秒在数个位置爆发出冰霜伤害。"}}
D.SpellTexts[228105]={Description={["6a16c740f2caed01:132"]="腐朽的爪牙死亡时，其骨骼将干枯，成为大地的一部分，如果复活将其重新唤醒，爪牙会死而复生并恢复全部生命值。"}}
D.SpellTexts[228116]={Description={["f00d87ab133ed9d8:86"]="你进入了PvP混乱区域。如果不离开这片区域，很快你将被标记为可以进行PvP战斗。"},Aura={["f00d87ab133ed9d8:86"]="你进入了PvP混乱区域。如果不离开这片区域，很快你将被标记为可以进行PvP战斗。"}}
D.SpellTexts[228128]={Aura={["eb4b8db0bb0372ab:20"]="可以调整天赋。"}}
D.SpellTexts[228132]={Description={["377453a46e53ff79:95"]="将神王的斧柄、沙索斯之颅与尼索格之颅组合在一起，制造斩龙者。"}}
D.SpellTexts[228139]={Description={["969509586cfb8289:160"]="永久性地对一件肩部护甲施放虚空乱流附魔。此附魔可以让穿着者从敌人的尸体上获取各种补给品。在此过程中这项赐福不会被消耗。"}}
D.SpellTexts[228140]={Aura={["0c633a4f9359950e:21"]="受到星光的灌注。"}}
D.SpellTexts[228187]={Description={["5d832d36df7556bb:111"]="高姆的三个头会分别喷出火焰、暗影或冰霜。如果受到影响的玩家过少，高姆会获得一层吐沫狂怒。"}}
D.SpellTexts[228194]={Aura={["df2f1ed9579b3bca:44"]="如果你继续停留在这一地区，将进入PvP状态！"}}
D.SpellTexts[228196]={Description={["1b75460a7df1e24f:65"]="永久放逐一个敌方恶魔，令其返回扭曲虚空。"},Aura={["1f80ff51544925c0:9"]="被放逐。"}}
D.SpellTexts[228201]={Description={["f83028425d6b273d:56"]="高姆挣脱了控制，机动性和攻击性都变得更高，持续%d。"},Aura={["b340883298d58037:51"]="高姆挣脱了控制，机动性和攻击性都变得更高。"}}
D.SpellTexts[228214]={Description={["955f0ba3b077750c:87"]="解决谜题可以制造一件随机的追随者装备物品。在此过程中谜题不会被消耗。"}}
D.SpellTexts[228215]={Aura={["050ad1b352d75964:14"]="被尘土蒙蔽了双眼！"}}
D.SpellTexts[228221]={Aura={["6c701e9d9b96bcfa:23"]="巴布丽特盯上你了！"}}
D.SpellTexts[228239]={Aura={["70a0394296a9e2bd:14"]="因恐惧而逃跑。"}}
D.SpellTexts[228248]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[228249]={Aura={["971bea604b9f85f1:22"]="成为炼狱箭的目标。"}}
D.SpellTexts[228254]={Description={["6dee83c20b989617:59"]="从附近所有敌人身上吸取生命值，将其转移给施法者。"}}
D.SpellTexts[228261]={Aura={["5f4e559e66120715:51"]="进入或离开烈焰花环会触发爆炸。"}}
D.SpellTexts[228270]={Aura={["72d86b35573af584:36"]="赫娅的光明之盾锁定了你！"}}
D.SpellTexts[228271]={Description={["eb560d64cdfd6977:46"]="从附近的邪能腐蚀源头采集一份样本。"}}
D.SpellTexts[228290]={Description={["1dc6f8b77a2142f4:21"]="进入你的定制鱼人卵。"},Aura={["c3aeb077e8370baa:11"]="正在孵化。"}}
D.SpellTexts[228299]={Description={["7418e6229bdd0935:77"]="喷出一团飘忽不定的火焰，对施法者前方的敌人造成火焰伤害。"}}
D.SpellTexts[228311]={Rank={["1044fc4216ed2ac5:5"]="等级 1"}}
D.SpellTexts[228334]={Description={["c6449272a00467c1:44"]="麦迪文之影可分裂成3个守护者的影像。"}}
D.SpellTexts[228337]={Description={["e1e66f3dec747692:78"]="释放施法者存储的所有能量，对附近所有的敌人造成奥术伤害。"}}
D.SpellTexts[228350]={Rank={["1044fc4216ed2ac5:5"]="等级 1"}}
D.SpellTexts[228358]={Aura={["2a95554319392622:42"]="受到法师的法术伤害时，被视为冻结的目标。"}}
D.SpellTexts[228365]={Aura={["fc7e4251f1a8f1de:91"]="昏迷并被冻结。如果目标被冰枪术、冰川尖刺或寒冰新星击中，将打破此效果。"}}
D.SpellTexts[228374]={Description={["90d0e5d4bd9c8c49:59"]="用一个水泡禁锢敌人的脑袋，令其缓慢窒息。"},Aura={["cf8a27746665325d:18"]="你正在窒息！"}}
D.SpellTexts[228378]={Description={["bbc2844480b353f3:39"]="你的英勇飞跃在落地时会伴随有电闪雷鸣的效果。"}}
D.SpellTexts[228381]={Description={["8729873474cc312f:28"]="制作一个落雷雕文。"}}
D.SpellTexts[228395]={Description={["44987fa857765fd5:63"]="施法者将目标的灵魂束缚在其体内，防止其死亡。"},Aura={["252d84d7b9ad74d2:19"]="免疫死亡。"}}
D.SpellTexts[228411]={Description={["2c9fa75628e17831:124"]="完成此世界任务可以让你进入法兰纳尔废墟，你可以在那里训练枯法者部队并获得堕夜精灵的声望。"}}
