D.SpellTexts[229495]={Aura={["693645c5791d1abc:19"]="容易遭受伤害。"}}
D.SpellTexts[228465]={Aura={["e5c769e8b10be623:15"]="追踪野兽。"}}
D.SpellTexts[228467]={Description={["1e65b55b96ebad6a:70"]="将沃格斯碎片和考扎克碎片组合成艾瑞达燃烧水晶。"}}
D.SpellTexts[228539]={Description={["537eb7c88cfe4a1d:45"]="将印记扔回马戈斯的小屋外的水中。"}}
D.SpellTexts[228545]={Rank={["7f5c1454467b72e1:10"]="变形"}}
D.SpellTexts[228555]={Description={["3add12dbb4065ddc:93"]="展现施法者的丑恶嘴脸，造成暗影伤害并使附近所有的敌人因恐惧而逃跑。"},Aura={["70a0394296a9e2bd:14"]="因恐惧而逃跑。"}}
D.SpellTexts[228563]={Aura={["73700d537d3a9880:27"]="你的下一个技能得到了强化。"}}
D.SpellTexts[228567]={Description={["1339c94e11419b55:40"]="猎犬召唤附近的盟友来协助它！"}}
D.SpellTexts[228575]={Description={["cc2f14a2157b8165:94"]="令施法者魅力四射，诱惑附近的敌人。如果被诱惑的效果叠加到100层，敌人将受到精神控制。"},Aura={["48dc3cc2089e37e5:22"]="诱惑附近的敌人。"}}
D.SpellTexts[228576]={Description={["a7827910fa4f2455:95"]="诱惑一名敌人，使其越来越迷恋施法者。叠加到100层时，目标将受到精神控制。"},Aura={["2b3341ffdf779be4:41"]="越来越沉迷于女招待的一颦一笑。"}}
D.SpellTexts[228578]={Aura={["66c41f91feb34d6e:15"]="被控制。"}}
D.SpellTexts[228599]={Rank={["5e500f93cabfbb92:8"]="神器"}}
D.SpellTexts[228600]={Aura={["7548450309cd002c:14"]="被冻结在原地。"}}
D.SpellTexts[228607]={Aura={["66c41f91feb34d6e:15"]="被控制。"}}
D.SpellTexts[228625]={Description={["1b4f4b1779d45b18:67"]="痛苦地哀嚎，对施法者正前方的敌人造成暗影伤害。"}}
D.SpellTexts[228630]={Description={["93dbe3573c73784a:29"]="虚空爆发变为瞬发。"}}
D.SpellTexts[228693]={Aura={["d86312dd54a6efe2:14"]="瘫痪。"}}
D.SpellTexts[228696]={Aura={["f372942e6fda6ac7:162"]="当你处于战场或竞技场时，角色属性会根据你的专精调整为预设的数值。\r\n\r\n你的平均物品等级会影响你所获得的属性数值。"}}
D.SpellTexts[228711]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[228758]={Aura={["8215de341fbe4033:50"]="与黑暗宣泄或盐水唾沫组合在一起时会更加致命。"}}
D.SpellTexts[228768]={Aura={["ac0c249e777ade27:49"]="与黑暗宣泄或烈火黏质组合在一起时会更加致命。"}}
D.SpellTexts[228769]={Aura={["821897a4c39ddae9:48"]="与盐水唾沫或烈火黏质组合在一起时会更加致命。"}}
D.SpellTexts[228796]={Aura={["b0d345ffda1e7b0e:76"]="效果结束时爆炸，对其他所有玩家造成相当于当前生命值的火焰伤害。"}}
D.SpellTexts[228807]={Aura={["d36908b5a904ab58:110"]="生命值低于25%时获得山丘之王的意志效果，受到的伤害降低，造成的伤害和受到的治疗效果提高。"}}
D.SpellTexts[228837]={Aura={["70a0394296a9e2bd:14"]="因恐惧而逃跑。"}}
D.SpellTexts[228839]={Description={["91f8c46a7ef226b3:79"]="夜之魇对地面喷吐暗影烈焰，召唤出一个可怕的怪物！"}}
D.SpellTexts[228849]={Aura={["5cad7da53269ff7e:117"]="对生命值低于30%的敌人使用近战攻击和技能将获得狼人狂乱效果。\r\n此效果每5分钟只能生效一次。"}}
D.SpellTexts[228854]={Description={["1a994e1a67428991:78"]="将冥狱深渊的迷雾灌注到海拉身体中，让她能够更频繁地施放巨喉之怒。"}}
D.SpellTexts[228855]={Aura={["4f98b1d8393d0727:8"]="被锁定。"}}
D.SpellTexts[228857]={Aura={["df9257a30fc48b7c:46"]="你永久成为了悲伤的守望者鹿角上的一部分。"}}
D.SpellTexts[228859]={Description={["937c66202f142a2d:150"]="解开书籍的封印，使你在为生命值低于25%的玩家治疗时可召唤一个幽灵盟友，为你所在的小队治疗。此效果每20秒只能生效一次。"},Aura={["4b725a418660c996:86"]="为生命值低于25%的玩家治疗时可召唤一个幽灵盟友。\r\n此效果每20秒只能生效一次。"}}
D.SpellTexts[228867]={Description={["b3c462e7e454de4a:39"]="投出一个火球，造成火焰伤害。"}}
D.SpellTexts[228869]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[228886]={Description={["e9e11f698331c5dc:88"]="向一名暮色卫队征服者展示暮色百合徽记。你必须在伪装状态下才能展示徽记。"}}
D.SpellTexts[228916]={Description={["c1dceccc2d3fcc95:139"]="破解书籍的封印，使你的攻击有一定几率释放一次泰坦之击，造成额外伤害。目标距离你越远，受到的伤害越高。"}}
D.SpellTexts[228919]={Description={["d7cbd0bdce5890c8:67"]="召唤或解散一条可供骑乘的暗水鳐鱼。\r\n\r\n只能在水下使用。"},Aura={["bbfd65611d840cc0:19"]="提高游泳速度。"}}
D.SpellTexts[228946]={Rank={["5e500f93cabfbb92:8"]="神器"}}
