D.SpellTexts[233206]={Description={["0920d706481d89c9:195"]="孟菲斯托斯遁入暗影并隐形，直到伊利丹完成驱逐暗影的施法。在此阶段中，孟菲斯托斯之影会持续出现并攻击伊利丹，阻止驱逐暗影的施法。"}}
