D.SpellTexts[235279]={Description={["f916bef470d68217:89"]="作为一名凶狠的猛禽德鲁伊，希萨莉·黑鸦对燃烧军团或任何其他敌人完全没有耐心。"},Aura={["ed36fbc2616a4bed:53"]="希萨莉·黑鸦是最具侵略性的猛禽德鲁伊。"}}
