D.SpellTexts[235305]={Description={["3351468587e7d4a8:121"]="军团囚禁的众多灵魂残存的希望，能够清除痛苦的正能量，在被折磨的幽魂受伤时可能出现。"},Aura={["3351468587e7d4a8:121"]="军团囚禁的众多灵魂残存的希望，能够清除痛苦的正能量，在被折磨的幽魂受伤时可能出现。"}}
D.SpellTexts[235306]={Aura={["11844eaf10cf7b28:71"]="近战攻击者命中时会受到物理伤害。\r\n\r\n非常重。坠落伤害加倍。"}}
