D.SpellTexts[235318]={Description={["d7060e39259e229c:77"]="黑锋骑士的一员。米妮瓦·悲鸦对生者毫无怜悯。"},Aura={["6e8a179b64cb2760:73"]="米妮瓦·悲鸦是一名鲜血死亡骑士，她对亡灵和斩首非常热衷。"}}
