D.SpellTexts[235414]={Description={["66e8bacec4ee96a9:125"]="现存的最强大，最年长的萨满之一。玛加萨·恐怖图腾一心想要得到末日石。她对更强力量的渴望是无法平息的。"},Aura={["010720bdd283bb26:90"]="玛加萨·恐怖图腾是恐怖图腾部落的强大领袖。她既是一名强大的领袖，也是一名强大的萨满。"}}
D.SpellTexts[235420]={Description={["5bc4a87846299feb:40"]="发射邪能弹药，造成大量伤害。"}}
