D.SpellTexts[235438]={Aura={["3fb6cf196639899a:13"]="被邪能感染。"}}
D.SpellTexts[235446]={Description={["a7c7c92ebd5ba751:114"]="莱斯特撕裂空间，制造出多个虚空裂隙。每个裂隙都会释放出若干个暗影残迹和一只阴影魔追赶玩家。"}}
