D.SpellTexts[235468]={Description={["fd66c8ca49932371:132"]="尽管莉莉安已经是亡灵，但她仍然唾弃一切被遗忘者和死灵法术。苔丝在白天或许是吉尔尼斯的公主，但在晚上，她就会化身成刺客大师。"},Aura={["9cb9b356016269f1:59"]="莉莉安和苔丝是两股极其强大且不容忽视的力量。"}}
