D.SpellTexts[235553]={Description={["86f3db9efb431d97:35"]="将施法者传送到破碎海滩。"}}
D.SpellTexts[235570]={Description={["d98d0514d58e68e9:29"]="装备一头被制服的惩罚者供玩家乘骑。"}}
