D.SpellTexts[235627]={Description={["93985601f720819e:23"]="移除一套重型护甲。"}}
D.SpellTexts[235630]={Description={["6c0a638e90293497:37"]="转移到竞技场的另一边。"}}
D.SpellTexts[235639]={Description={["11f38fb8d4fd80e3:29"]="施法者免疫所有伤害。"},Aura={["9c9b4d7eae52d7eb:7"]="免疫。"}}
D.SpellTexts[235641]={Description={["eae56c0eb3b51dd3:50"]="击杀一个目标可以使英勇飞跃的冷却时间降低25%。"},Aura={["eae56c0eb3b51dd3:50"]="击杀一个目标可以使英勇飞跃的冷却时间降低25%。"}}
D.SpellTexts[235652]={Description={["ef7b204db3992f5e:48"]="士兵中毒，需要武僧玩家驱散。"},Aura={["39101ad904e14b66:13"]="可以清创生血。"}}
D.SpellTexts[235656]={Description={["f3381722bd7100df:98"]="施法者脚步沉重，每走一步都会造成震荡波，震退附近的敌人。"},Aura={["fe61f082f26a01f1:57"]="该生物每走一步都能击退附近的敌人。"}}
D.SpellTexts[235658]={Aura={["652ca1903afc0787:58"]="周期性地向附近敌人的位置发射爆炸孢子。"}}
D.SpellTexts[235660]={Description={["4ffe761423c302cf:98"]="施法者与时间线的联结变得不稳定。许多技能会在几秒后在同样的位置引发回响。"},Aura={["90029f10ec450a1b:29"]="技能会发生回响。"}}
D.SpellTexts[235669]={Description={["0f7e7fd55ec3a8a0:54"]="从帽子中召唤出一只兔子，接触时当然会发生爆炸。"}}
D.SpellTexts[235709]={Description={["0673130bbcc26096:21"]="向你的敌人投掷一张卡牌。"}}
D.SpellTexts[235710]={Description={["0ca179a125491440:22"]="摧毁一个军团传送门。"}}
D.SpellTexts[235712]={Aura={["c85b0cd9c957fee6:29"]="瞄准射击可以在移动中施放。"}}
D.SpellTexts[235728]={Description={["4ea18f2ec6bb3fcf:56"]="激励附近的士兵，提高他们的攻击强度和生命值。"},Aura={["7ef231e1e90b44e2:22"]="激励附近的盟友。"}}
D.SpellTexts[235731]={Description={["2868d2e439586637:126"]="永久性地对一件肩部护甲施放工匠的恩赐附魔。此附魔可以让穿着者从敌人的尸体上获取链齿容器。"}}
D.SpellTexts[235745]={Description={["b69c40fd66e0e1dc:66"]="发射一颗闪电球，对附近所有的敌人造成自然伤害。"}}
D.SpellTexts[235748]={Description={["8bcff84142af982e:81"]="施法者发出强大的咆哮，对前方的所有敌人造成物理伤害。"}}
D.SpellTexts[235749]={Description={["8cd9f46beac59fea:119"]="施法者用头部猛砸前方的所有目标。受害者受到物理伤害并被击退，且威胁值降低。"}}
D.SpellTexts[235753]={Description={["1ec59e8292354ef5:27"]="制作布甲爆头者。"}}
D.SpellTexts[235754]={Description={["9790840c2febcf45:25"]="制作毛皮爆头者。"}}
D.SpellTexts[235755]={Description={["586d38d1f346dba4:24"]="制作链甲爆头者。"}}
D.SpellTexts[235756]={Description={["a533756bafd152aa:24"]="制作重甲爆头者。"}}
D.SpellTexts[235757]={Description={["514c1f05897fecf0:34"]="受到威胁时，这个生物会适应周围的环境。"}}
D.SpellTexts[235762]={Description={["499c02e8d3cafbc5:129"]="施法者制造出锥形闪电，对前方所有敌人造成自然伤害。被闪电击中的受害者受到自然伤害。"}}
D.SpellTexts[235764]={Description={["247ac955b9b13c4a:91"]="召唤或解散一头暗孢法力鳐。这种坐骑的速度会根据你的骑术等级和所在区域改变。"}}
D.SpellTexts[235773]={Description={["30e0519ab5ed4fdf:21"]="带着一顶有趣的帽子。"},Aura={["0ec8519acd3243ef:16"]="看起来光彩照人！"}}
D.SpellTexts[235775]={Description={["66e913fa249ae7d9:32"]="制作可充电的里弗斯电池。"}}
D.SpellTexts[235781]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[235784]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[235786]={Description={["1d3249f9a48a037e:8"]="切割宝石。"},Aura={["34908f45c29acfc2:51"]="切割一块宝石。切割的次数越少，宝石的品质就越高。"}}
D.SpellTexts[235792]={Description={["9e659dfa39392b9d:53"]="兔子爆炸，对附近所有敌人造成奥术伤害。"}}
D.SpellTexts[235794]={Description={["24816fa2fa70de11:126"]="永久性地对一件肩部护甲施放收获附魔。此附魔可以让穿着者从敌人的尸体上获取一堆宠物补给。"}}
D.SpellTexts[235818]={Aura={["fa9d2d03f458c84c:25"]="踩着一桶风暴蜜酒。"}}
D.SpellTexts[235837]={Description={["cb8c2a124e8be799:49"]="向目标射出一支箭，造成物理伤害。"}}
D.SpellTexts[235845]={Description={["806e755bd56ae4ce:48"]="瞬发攻击，对一个敌人造成物理伤害。"}}
D.SpellTexts[235847]={Description={["e202b39850de4321:20"]="造成物理伤害。"}}
D.SpellTexts[235855]={Description={["777c44df6712687e:41"]="从天空中引导邪能流星风暴。"},Aura={["777c44df6712687e:41"]="从天空中引导邪能流星风暴。"}}
D.SpellTexts[235857]={Description={["eafb820c8deed9b1:57"]="施法者向目标投掷一根长矛，造成物理伤害。"}}
D.SpellTexts[235866]={Description={["8284f53f20c7405c:47"]="滞留在气泡中会导致玩家慢慢溺水。"}}
D.SpellTexts[235870]={Description={["dec04701ca6b27d4:63"]="龙息术必定爆击并能计入炽热连击。"}}
D.SpellTexts[235871]={Description={["c8918250ff971a85:24"]="正在从暗影中召唤。"},Aura={["c8918250ff971a85:24"]="正在从暗影中召唤。"}}
D.SpellTexts[235877]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[235886]={Description={["1c96a40f3be29ce2:120"]="施法者召唤族群成员跑过战场。位于其路径上的所有玩家都将受到物理伤害。"}}
D.SpellTexts[235887]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
