D.SpellTexts[235894]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[235897]={Description={["3bf495a67c291d63:51"]="击杀一个目标会使神圣马驹的冷却时间缩短25%。"},Aura={["3bf495a67c291d63:51"]="击杀一个目标会使神圣马驹的冷却时间缩短25%。"}}
D.SpellTexts[235903]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[235904]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
