D.SpellTexts[235910]={Aura={["3bcd05a2d384baad:18"]="被踩在脚下。"}}
D.SpellTexts[235914]={Description={["00a427c8e2600e21:91"]="掷出3个奥术陷阱，当敌人靠近时爆炸，对4码内的所有人造成奥术伤害。"}}
D.SpellTexts[235935]={Description={["ddcb9c953992ac6a:75"]="猛击施法者周围的地面，对附近的所有敌人造成物理伤害。"}}
D.SpellTexts[235941]={Rank={["b4c9e893f741fb56:11"]="荣誉天赋"}}
D.SpellTexts[235942]={Description={["88ab9e49dfd0760e:73"]="烂口开始吞噬附近尸体上的腐烂血肉，在进食的同时为自己恢复生命值。"},Aura={["e09e582dc286031a:29"]="每2秒恢复5%的生命值。"}}
D.SpellTexts[235948]={Description={["a84868a2ac939053:35"]="召唤一群小鬼来帮助施法者。"}}
D.SpellTexts[235950]={Description={["6dd98864c1cad9b7:28"]="对一名敌人造成火焰伤害。"}}
D.SpellTexts[235952]={Aura={["9837ecbb18100dac:48"]="昏迷。\r\n定身。\r\n每秒受到一次暗影伤害。"}}
D.SpellTexts[235955]={Description={["dc13d3d3747cb138:173"]="施法者在随机位置召唤太阳之力从天而降，在每个冲击点形成一个太阳耀斑。太阳耀斑稍后迅速扩大，对其影响范围内的所有玩家造成火焰伤害。"}}
D.SpellTexts[235957]={Aura={["158a45a534c81f04:19"]="正在召唤邪能陷阱。"}}
