D.SpellTexts[239767]={Description={["b9ca2df86623bed3:45"]="召唤或解散一头可供骑乘的红色其拉主战坦克。"}}
D.SpellTexts[239769]={Description={["3a872a55a22f3e1e:48"]="召唤或解散一头可供骑乘的紫色其拉主战坦克。"}}
D.SpellTexts[239770]={Description={["c7a944fa76a644c1:47"]="召唤或解散一头可供骑乘的黑色其拉主战坦克。"}}
D.SpellTexts[239786]={Description={["38ab2ffd82d2f99e:44"]="腐蚀附近的一具尸体，强迫其行动。"}}
D.SpellTexts[239790]={Description={["7451a5056c32d7fe:58"]="邪恶的魔法使尸体起死回生的同时也在腐蚀它。"},Aura={["7451a5056c32d7fe:58"]="邪恶的魔法使尸体起死回生的同时也在腐蚀它。"}}
D.SpellTexts[239810]={Aura={["2aa1dc77164abc1e:27"]="无法攻击或施放法术！"}}
D.SpellTexts[239815]={Description={["6ff17959e8c17300:63"]="召唤一阵邪能火雨，对冲击区域造成火焰伤害。"}}
D.SpellTexts[239818]={Aura={["9a2cd2fa3045010b:9"]="沉默。"}}
D.SpellTexts[239826]={Aura={["b51235fdebbc44d0:20"]="坠落速度降低。"}}
D.SpellTexts[239829]={Description={["1aa7d7432e494308:68"]="召唤或解散你的狩猎大师的忠诚狼鹰。这是一种飞行坐骑。"}}
D.SpellTexts[239832]={Description={["6ff17959e8c17300:63"]="召唤一阵邪能火雨，对冲击区域造成火焰伤害。"},Aura={["bcc33512f7bba5ef:11"]="邪能如雨。"}}
D.SpellTexts[239882]={Description={["9fd70450e992fc29:84"]="桑德兰祝福目标，受祝福的目标不会被移出风神王座。"},Aura={["ee7b96a3d353c7d2:80"]="你不会被任何一位风领主移出风神王座。"}}
D.SpellTexts[239891]={Aura={["67caf6ac0718fa95:40"]="无法进食或饮水。\r\n被狂野亡灵追逐。"}}
D.SpellTexts[239897]={Description={["269c3cbe929b61b3:81"]="使施法者高高跃起，着陆时对附近所有敌人造成物理伤害。"},Aura={["ca6cd7b0458e3d3d:17"]="有格调地坠落！"}}
D.SpellTexts[239899]={Description={["2cfde1f96271689c:75"]="跳向目标，落地时对附近的所有敌人造成物理伤害。"}}
D.SpellTexts[239905]={Aura={["e6fbe7e473ebc067:73"]="获得技能，可以像猢狲一样跳跃。只能在邪能要塞使用。"}}
D.SpellTexts[239906]={Description={["a4932ef7a15abfa2:37"]="向你的敌人扔出小桶的风暴蜜酒！"}}
D.SpellTexts[239932]={Aura={["bb84e767555623b6:33"]="被邪火强化的近战攻击。"}}
D.SpellTexts[239935]={Description={["578941038f21fb6a:49"]="立即将美猴王的法杖还给其主人。"}}
D.SpellTexts[239943]={Description={["008304ec1f0a5645:89"]="向敌人扔出一个装满蜘蛛的罐子，造成物理伤害并召唤蜘蛛协助施法者。"}}
D.SpellTexts[239954]={Description={["c9d916ed04ab367c:34"]="召唤一个恶魔卫士协助施法者。"}}
D.SpellTexts[239963]={Aura={["501304559b68ec7a:14"]="治愈伤口。"}}
D.SpellTexts[239966]={Description={["66e77c21331ffe8c:111"]="获得抗魔联军战争物资时有几率获得额外的物资。\r\n\r\n向指挥官钱伯斯报告以获得这个奖励。"},Aura={["95ea618df39337f6:70"]="获得抗魔联军战争物资时有几率获得额外的物资。"}}
D.SpellTexts[239967]={Description={["33b8fc4c7496daff:154"]="虚空干扰器激活时，你每天都可以回到破碎海滩完成一个任务，获得一枚免费的破碎命运印记。\r\n\r\n向指挥官钱伯斯报告以获得这个奖励。"},Aura={["09aa015802b550c3:113"]="虚空干扰器激活时，你每天都可以回到破碎海滩完成一个任务，获得一枚免费的破碎命运印记。"}}
D.SpellTexts[239968]={Description={["8e2d3a5025c9826b:134"]="如果你在破碎群岛进行额外拾取时没有如愿，有几率返还使用的破碎命运印记。\r\n\r\n向指挥官钱伯斯报告以获得这个奖励。"},Aura={["91043adc712ed657:93"]="如果你在破碎群岛进行额外掷骰时失败，有几率返还使用的破碎命运印记。"}}
D.SpellTexts[239969]={Description={["fbb456ff5024b1ee:93"]="获得虚空碎片时有几率得到额外的虚空碎片。\r\n\r\n向指挥官钱伯斯报告以获得这个奖励。"},Aura={["3e6d22abce7c3814:52"]="获得虚空碎片时有几率得到额外的虚空碎片。"}}
D.SpellTexts[239989]={Description={["fab6b6c1d5136796:116"]="施法者召唤一头冰霜巨龙，用寒冰龙息扫过战场，对沿途的所有玩家造成冰霜伤害。"}}
D.SpellTexts[240000]={Aura={["56353fc0b7105e6d:7"]="定身。"}}
D.SpellTexts[240009]={Aura={["a228609abb56905f:7"]="恐惧。"}}
D.SpellTexts[240028]={Aura={["b7eb4e86f007b051:27"]="心怀对未知的恐惧。"}}
D.SpellTexts[240030]={Description={["7ffbfa50676e7677:22"]="玛加萨正在跟随你。"},Aura={["7ffbfa50676e7677:22"]="玛加萨正在跟随你。"}}
D.SpellTexts[240043]={Description={["d94693a6398ac269:115"]="魔网能量在你的体内涌动，造成的伤害提高15%，同时在你攻击敌人时有时会召唤魔网能量箭。"},Aura={["9f8962fffad51404:27"]="你被魔网能量强化。"}}
D.SpellTexts[240050]={Description={["2ec135e4d70400f3:41"]="魔网能量汇聚的箭矢，造成奥术伤害。"}}
D.SpellTexts[240059]={Description={["347d047ee7297639:14"]="吸收伤害。"}}
D.SpellTexts[240064]={Description={["787219c43f013edb:42"]="右键点击以召唤或解散这个小伙伴。"}}
D.SpellTexts[240094]={Description={["b76387a154bbbcd2:89"]="使用女王的优雅织布机，将你收集的丝线和布料缝合在一起。"}}
D.SpellTexts[240100]={Aura={["09c4de5b9f17a716:41"]="被火焰伤害击中时有几率昏迷。"}}
D.SpellTexts[240102]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
