D.SpellTexts[240138]={Description={["1032948b89caf924:62"]="召唤一个积怨之魂。\r\n\r\n你必须在阿苏纳的“活水”伊丽西娅附近。"}}
D.SpellTexts[240139]={Aura={["017c35ce495f230d:29"]="致盲。\r\n命中几率降低至0%。\r\n"}}
D.SpellTexts[240140]={Aura={["d2debb2e6fcafaa7:21"]="命中几率降低至0%。"}}
D.SpellTexts[240141]={Description={["fe788c2ae0ea4045:75"]="在目标位置制造一片尘云，使所有站在其中的玩家致盲。"},Aura={["d2debb2e6fcafaa7:21"]="命中几率降低至0%。"}}
D.SpellTexts[240142]={Description={["0e469035a4f9c68e:183"]="你召唤末日石的力量，牺牲10%的最大生命值，使你造成的所有伤害和治疗效果提高20%，持续10秒，并使你受到的伤害降低20%，持续10秒。此效果最多可叠加10次。"}}
D.SpellTexts[240144]={Description={["cf0301a987f29962:54"]="向目标投掷一块“泥巴”，造成自然伤害。"}}
D.SpellTexts[240146]={Description={["d0f696c5a9e46c56:44"]="麦格尼正通过悬浮水晶与你对话。"},Aura={["d0f696c5a9e46c56:44"]="麦格尼正通过悬浮水晶与你对话。"}}
