D.SpellTexts[240165]={Aura={["13e5b5ad0d726b8e:17"]="正在施加急救。"}}
D.SpellTexts[240169]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[240177]={Description={["ba8e2b100dbabf8d:34"]="召唤一个克瓦迪尔的勇士协助你。"},Aura={["ba8e2b100dbabf8d:34"]="召唤一个克瓦迪尔的勇士协助你。"}}
D.SpellTexts[240194]={Description={["ce9ea1b5b51df878:117"]="召唤一个邪能散播器，在其下方制造出一片燃烧魔藤。站在魔藤上的玩家每秒受到一次火焰伤害。"}}
