D.SpellTexts[240319]={Description={["f195a9e243496ee1:68"]="这枚孵化中的蛋就要出壳了。施法结束后，一只鱼人蝌蚪将会出生。"}}
D.SpellTexts[240327]={Description={["094c0bd9554f1afa:133"]="施法者让邪能灵魂围绕着目标，缓慢地向内坍缩。与灵魂接触会使受害者受到火焰伤害。"}}
