D.SpellTexts[240353]={Description={["d7b7ccdef434f5c7:99"]="在至高岭苍穹石使用，将你收集到的材料打造成遗忘英雄之锤。"}}
D.SpellTexts[240361]={Description={["2dd954643beb5107:135"]="岩浆池剧烈喷发，将熔火邪能抛向高空，最终坠向地面，对附近敌人造成火焰伤害。"}}
