D.SpellTexts[240386]={Description={["1728d9469170b867:84"]="在阿苏纳的塞莉娅身边使用。这是破碎群岛唯一可以用来制作守护之鳞的魔法阵列。"}}
D.SpellTexts[240400]={Description={["1305b0fdacbb7712:125"]="施法者腐化你脚下的土地，吸引腐臭蜂群，对站在其范围内的所有玩家造成自然伤害。"}}
