D.SpellTexts[240439]={Description={["a7b4b4127ce2f1d3:61"]="从这个记录着恐怖生物的典籍中召唤一个奥术恐魔。"}}
D.SpellTexts[240447]={Aura={["82984a174122ec78:25"]="持续时间结束时造成地震。"}}
