D.SpellTexts[240490]={Description={["172cfb37f5506e82:79"]="受爆蛋器的影响，海怪的蛋急剧膨胀并最终爆炸。"}}
D.SpellTexts[240496]={Description={["5d1dea18abdb14d7:37"]="传送到恐惧快递号的装货码头。"}}
D.SpellTexts[240498]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
