D.SpellTexts[240880]={Description={["494bff7f18968c2c:149"]="施法者向附近的所有腐溃毒气投掷活性催化剂。催化剂会使毒气产生剧烈爆炸，对毒气中的所有玩家造成火焰伤害。"}}
