D.SpellTexts[241593]={Description={["c9752ce057bc9721:99"]="古老的结界保卫着古墓的最深处，防止动荡的灵魂在爆炸时影响其他盟友。"},Aura={["46412dd6e3f5317b:51"]="动荡的灵魂爆炸时不会对盟友造成伤害。"}}
