D.SpellTexts[242450]={Description={["76ac69bb9310520e:59"]="收集残虐角斗士的邪纹布甲套装外观。"}}
D.SpellTexts[242452]={Description={["7794a8958efbf12c:61"]="收集精锐残虐角斗士的板甲套装外观。"}}
D.SpellTexts[242454]={Description={["5be2fc620b1c723d:56"]="收集残虐角斗士的板甲套装外观。"}}
D.SpellTexts[242466]={Aura={["c4727c1431f5873b:21"]="造成暗影伤害。"}}
D.SpellTexts[242473]={Description={["d12f9ca3c206369a:20"]="吃掉饼干。"},Aura={["42352eea5b16f80f:21"]="你感觉自己回到了童年。"}}
D.SpellTexts[242477]={Description={["ea048e948904abe3:47"]="喂食你的宠物小伙伴，使其被邪能腐蚀。"},Aura={["8775ceb936b5e900:21"]="被邪能腐蚀。"}}
D.SpellTexts[242479]={Description={["df1e9a0d436179b8:40"]="施法者将其生命力与目标链接。"},Aura={["ddb216bf88ff1ad6:12"]="分享生命。"}}
D.SpellTexts[242485]={Description={["07faaca11e405dd8:64"]="立即对周围所有敌人投掷飞刀，造成物理伤害。"}}
D.SpellTexts[242495]={Description={["a736509ffbf496e8:11"]="施放一个法术。"}}
D.SpellTexts[242496]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[242498]={Description={["0a1a55043c0f6dab:61"]="收集残虐争斗者的恐怖板甲套装外观。"}}
D.SpellTexts[242500]={Description={["b78b80ba18eabe85:58"]="收集残虐争斗者的邪皮护甲套装外观。"}}
D.SpellTexts[242502]={Description={["89d66543b1cfa112:61"]="收集残虐争斗者的龙皮护甲套装外观。"}}
D.SpellTexts[242504]={Description={["74f5d631ac22abce:56"]="收集残虐争斗者的链甲套装外观。"}}
D.SpellTexts[242506]={Description={["10c1a681040a81f2:55"]="收集残虐争斗者的丝质布甲套装外观。"}}
D.SpellTexts[242508]={Description={["787140dbb0228222:59"]="收集残虐争斗者的铁皮护甲套装外观。"}}
D.SpellTexts[242510]={Description={["4ea4d69af466332d:57"]="收集残虐争斗者的板鳞甲套装外观。"}}
D.SpellTexts[242512]={Description={["9f701bed3577f8e4:56"]="收集残虐争斗者的绸缎布甲套装外观。"}}
D.SpellTexts[242514]={Description={["2c444af34f712906:58"]="收集残虐争斗者的皮甲套装外观。"}}
D.SpellTexts[242516]={Description={["2461dbc15b133b40:59"]="收集残虐争斗者的环甲套装外观。"}}
D.SpellTexts[242518]={Description={["ad3e5b1dec7caef2:59"]="收集残虐争斗者的邪纹布甲套装外观。"}}
D.SpellTexts[242520]={Description={["4b519904db48ea59:56"]="收集残虐争斗者的板甲套装外观。"}}
D.SpellTexts[242521]={Description={["4b519904db48ea59:56"]="收集残虐争斗者的板甲套装外观。"}}
D.SpellTexts[242529]={Description={["bfe6e17c110a41ff:40"]="从移动传送门中救出魔犬幼崽。"},Aura={["8a647328af9b94c3:30"]="抚养魔犬幼崽。"}}
D.SpellTexts[242559]={Description={["ed60bee2cb4e05d9:39"]="为入侵演习部署地面目标。"},Aura={["cb6a49ac227afbc3:38"]="发现可腐化的生命形式，消灭。"}}
D.SpellTexts[242569]={Aura={["31a440b91e77fbca:40"]="无敌。\r\n无法攻击或施法。"}}
D.SpellTexts[242570]={Aura={["1e0ddd1243ba11bf:27"]="一只灵魂猫头鹰正在协助你。"}}
D.SpellTexts[242581]={Aura={["dbfb4adc730a66a1:35"]="火焰之息的冷却时间已重置。"}}
D.SpellTexts[242583]={Description={["097a3fff44caa99c:18"]="力量提高。"}}
D.SpellTexts[242587]={Description={["af6842da7131d6b9:24"]="一只逃脱的小鬼正在攻击你。"}}
D.SpellTexts[242591]={Description={["f8f95f212e1af110:31"]="一只逃脱的魔犬正在攻击你。"}}
D.SpellTexts[242595]={Description={["a81e5278ebb23ac5:37"]="一只恶魔与你一起穿过传送门逃脱了。"}}
D.SpellTexts[242702]={Description={["647937985b56e2bf:68"]="使用灌注了圣光之力的武器攻击目标，造成神圣伤害。"}}
D.SpellTexts[242615]={Description={["d17bfe209cfba7b5:35"]="攻击一名敌人，造成神圣伤害。"}}
D.SpellTexts[242639]={Aura={["d047262752c5df2a:43"]="持续时间结束时造成大量暗影伤害。"}}
D.SpellTexts[242651]={Description={["927bb460db436507:57"]="欺瞒周围的敌人，使他们在战斗中帮助施法者。"}}
D.SpellTexts[242653]={Aura={["096219e7b8e2e098:8"]="被魅惑。"}}
D.SpellTexts[242676]={Description={["4e0d20729b6782bf:32"]="抓住一名乘客，并将其拽到载具上来。"}}
D.SpellTexts[242689]={Description={["da1de7fec73d3971:57"]="用雕像隐藏的圣光之力驱散一个虚空具象。"}}
D.SpellTexts[242690]={Aura={["966a1630e623ba8f:32"]="无法从辛多雷之怨受益。"}}
D.SpellTexts[242693]={Description={["53a449924a9748af:33"]="召唤自然之力治疗盟友。"}}
D.SpellTexts[242696]={Description={["721e693ea89455f5:137"]="暗影聚集，使你无法对8码以外的目标，友方玩家或敌人使用技能。\r\n\r\n此外，玩家还会受到窒息之影的影响。"},Aura={["416a9a429c12d6af:25"]="视野被限制为8码。"}}
D.SpellTexts[242705]={Aura={["f7a703ab51570372:31"]="你的终结技不消耗能量。"}}
D.SpellTexts[242713]={Aura={["12d3d76b91bb90ba:31"]="持续时间结束时召唤光耀之眼。"}}
D.SpellTexts[242715]={Description={["cbdbe7eda1fa765c:71"]="施法者爆发出神圣能量，对附近所有敌人造成神圣伤害。"},Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[242722]={Description={["1bbec0754bf91fcc:20"]="造成的伤害提高。"}}
D.SpellTexts[242724]={Aura={["a228609abb56905f:7"]="恐惧。"}}
D.SpellTexts[242726]={Description={["fb8f93e395e92592:30"]="安度因·乌瑞恩国王正在跟随你。"}}
D.SpellTexts[242739]={Aura={["70a0394296a9e2bd:14"]="因恐惧而逃跑。"}}
D.SpellTexts[242754]={Description={["1fdd4cf357aea49a:86"]="向目标投掷强化后的盾牌，对目标及其周围的所有敌人造成神圣伤害。"}}
D.SpellTexts[242785]={Description={["8a80480208b677a9:41"]="用一颗高爆炮弹轰击目标。"}}
D.SpellTexts[242792]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[242806]={Description={["4a950a327d92fbdf:54"]="收集恶魔暴君的武器附魔外观。"}}
D.SpellTexts[242813]={Description={["55f1ca5a126c0b63:92"]="用不容置疑的声音、姿态和外观魅惑目标。如果目标的生命值降至30%以下则会打破此效果。"},Aura={["c035a46a27582fb3:46"]="被魅惑。生命值降至30%以下时取消此效果。"}}
D.SpellTexts[242824]={Description={["0e6be2766b4fbb7f:68"]="飞扑突袭目标，落地时对附近的所有敌人造成物理伤害。"}}
D.SpellTexts[242828]={Description={["fa5e8b08b8249d4d:68"]="痛击附近的所有敌人，造成物理伤害并使其流血。"},Aura={["8725a32dadf6ad66:9"]="流血。"}}
D.SpellTexts[242830]={Description={["e6cadd118edf511e:61"]="这些小蜘蛛体内涌动着布满邪能的体液，随时可能破裂。"},Aura={["2fc71fcf0c858a98:23"]="死亡时制造一个邪能之池。"}}
D.SpellTexts[242833]={Aura={["e6ebc133d2dc9b24:40"]="在虚空世界的碎片中。无法使用坐骑。"}}
D.SpellTexts[242835]={Description={["950b17efdbe64c8e:56"]="使你的武器看上去像用过恶魔暴君附魔一样。"}}
D.SpellTexts[242848]={Aura={["6c1885d3f32873f4:22"]="正在接收虚空能量。"}}
D.SpellTexts[242874]={Description={["f40ddfa96f719c76:45"]="召唤或解散你的至高岭大角鹿。"}}
D.SpellTexts[242875]={Description={["9e0af0aed042eceb:39"]="召唤或解散你的野生梦境角马。"}}
D.SpellTexts[242878]={Aura={["bdcedc2229274a9d:41"]="向附近的敌人发射暗影能量球。"}}
D.SpellTexts[242881]={Description={["e1a45efb03b995b6:48"]="召唤或解散一只可供骑乘的云翼角鹰兽。"}}
D.SpellTexts[242882]={Description={["6236c4980f1fa689:41"]="召唤或解散你的瓦拉加尔风暴之翼幼龙。"}}
D.SpellTexts[242896]={Description={["e0ab6ef47ce8c199:37"]="召唤或解散你的勇猛的战狐"}}
D.SpellTexts[242908]={Aura={["04f77ffed063257f:15"]="无法逃脱。"}}
D.SpellTexts[242914]={Description={["c9338e6665d911d5:100"]="召唤一个暗影宝珠，从施法者所在位置向外飞行，对其经过的敌人造成暗影伤害。"}}
D.SpellTexts[242916]={Description={["7487ca2ec2aecda3:20"]="会提供神器能量吗？"},Aura={["5cae47144e63885f:33"]="也许你不该吃它的……"}}
D.SpellTexts[242932]={Description={["f2af97d957f3893c:13"]="拿起麦克风。"},Aura={["dca4f234be3b187b:31"]="只为摆个样子。她的声音非常有力。"}}
D.SpellTexts[242951]={Description={["44f8c20df729c798:136"]="坎雷萨德变为恶魔形态，使其所有法术的伤害提高，但这会抽取他的能量。当能量将至0时，坎雷萨德将变回普通形态。"},Aura={["729628a3bbe02056:39"]="变形。所有法术的伤害提高。"}}
D.SpellTexts[242955]={Description={["7cba95e4eb2b9581:30"]="对一名敌人造成暗影伤害。"}}
D.SpellTexts[242960]={Aura={["36eb7ffcf3a73217:106"]="正在虚空中游走。难以被虚灵和他们的爪牙发现。\r\n\r\n解散所有召唤物。无法使用坐骑。"}}
D.SpellTexts[242962]={Aura={["e7feda3d277e065a:46"]="正在窥视虚空。可以更容易侦测到玩家。"}}
D.SpellTexts[242975]={Description={["f6e92c42d58f6dff:54"]="允许一只目标战斗宠物坐着魔法飞碟与你一起飞行。"},Aura={["8f7a219daa4fc312:16"]="坐着飞碟飞行。"}}
D.SpellTexts[242980]={Description={["0d0ff74e5132f5fb:69"]="被虚空之井排斥。造成相当于目标生命值5%的伤害，并将其击退。"}}
D.SpellTexts[242982]={Description={["0537e91cb9885709:43"]="周期性地在邪能风暴下方施放闪电。 "}}
D.SpellTexts[242983]={Description={["7970cec0c5956105:18"]="召唤一条烈焰裂隙。"}}
D.SpellTexts[242985]={Description={["200003282fbe8511:26"]="你进入了邪能风暴。"},Aura={["d4a870da34d9bfb9:28"]="有几率被邪能闪电击中。"}}
D.SpellTexts[243004]={Description={["3eecf26a1deb5833:69"]="施法者被腐烂之雾包裹，迷雾范围之外的人无法将其选为目标。"},Aura={["ace20406af260e5b:37"]="无法被迷雾屏障外的人选为目标。"}}
D.SpellTexts[243019]={Aura={["231ee54de91419d8:24"]="奥蕾莉亚刚刚来帮助过你。"}}
D.SpellTexts[243025]={Description={["ed950c75d4385248:42"]="召唤或解散你的谜语人的灵蛇。"}}
D.SpellTexts[243027]={Description={["04658f6e35fd9925:83"]="施法者用暗影能量护盾保护主人，使其免受任何伤害。"},Aura={["7a8d3eb9f126fd5c:18"]="免疫所有伤害。"}}
D.SpellTexts[243055]={Description={["2f914a20f371832b:64"]="投出一块贝壳，使目标下马。无法对110级以上的目标使用。"}}
D.SpellTexts[243062]={Aura={["81430b25b6b70dea:64"]="正在虚空中游走。难以被虚灵和他们的爪牙发现。"}}
D.SpellTexts[243069]={Description={["784a0429e530f47a:40"]="这个实体很快会溜回虚空之中。"},Aura={["784a0429e530f47a:40"]="这个实体很快会溜回虚空之中。"}}
D.SpellTexts[243089]={Description={["1240f0a7ca0ff5ba:10"]="跳起来吧！"},Aura={["a86f1700422607ab:28"]="拍卖行里的舞会！"}}
D.SpellTexts[243136]={Description={["787219c43f013edb:42"]="右键点击以召唤或解散这个小伙伴。"}}
D.SpellTexts[243138]={Description={["f83c308194f8c5ee:6"]="跳舞！"}}
D.SpellTexts[243139]={Description={["10d099ca02980ea1:24"]="戴上守望者的伪装。"},Aura={["716477d5601703a0:19"]="守望者的一员。"}}
D.SpellTexts[243156]={Description={["02ab3ca964b4befa:115"]="将施法者传送至邪能之槌号。\r\n\r\n在邪能之槌号再次施放传送门：邪能之槌号将把施法者传回原先的位置附近。"}}
D.SpellTexts[243158]={Description={["e484027a45636c1b:48"]="缴械一名敌人，使其无法使用武器。"},Aura={["25d68dc2f8476e7b:19"]="没有装备武器。"}}
D.SpellTexts[243185]={Description={["269c3cbe929b61b3:81"]="使施法者高高跃起，着陆时对附近所有敌人造成物理伤害。"},Aura={["ca6cd7b0458e3d3d:17"]="有格调地坠落！"}}
D.SpellTexts[243196]={Aura={["dd96a43e06c82ce7:10"]="粉碎！"}}
D.SpellTexts[243208]={Description={["2c20039556b52186:57"]="传送到破碎海滩的新月神殿。"},Aura={["8fc55084995a35a7:31"]="传送到新月神殿。"}}
D.SpellTexts[243209]={Description={["df84292d4aa4bd26:75"]="在地上放置偷来的清扫器。它的能量不多，坚持不了太久。"}}
D.SpellTexts[243212]={Aura={["b19894d97c415bfe:20"]="屈服于虚空。"}}
D.SpellTexts[243221]={Description={["605ac55f4a1ef718:43"]="造成相当于目标生命值3-5%的暗影伤害。"}}
D.SpellTexts[243232]={Description={["b718471ddb10bd5a:46"]="将使用者化作邪能流星，投向远方。"}}
D.SpellTexts[243245]={Description={["60ffc067a1f8916e:56"]="将施法者向前传送20码，直到碰到障碍物为止。"}}
D.SpellTexts[243246]={Description={["5a646b535015912e:34"]="将你传送数次。"}}
D.SpellTexts[243247]={Description={["e2c57b4a1edea6b3:75"]="海盗风格的眼罩将展示你无可抵抗的魅力。"},Aura={["1325ace2f698b6fb:46"]="简直太有型了，真不敢相信这是从桶里翻出来的！"}}
D.SpellTexts[243248]={Description={["52a58bd1f78acafe:96"]="召唤一个装着神秘眼罩的圆桶，供你和你的朋友使用。结果绝对令你难以置信！"},Aura={["1325ace2f698b6fb:46"]="简直太有型了，真不敢相信这是从桶里翻出来的！"}}
D.SpellTexts[243249]={Description={["223efa9bc22e1b4c:55"]="最近使用过眼罩桶，无法再次使用了。"},Aura={["223efa9bc22e1b4c:55"]="最近使用过眼罩桶，无法再次使用了。"}}
D.SpellTexts[243256]={Description={["3b80b186ed64f839:48"]="催人泪下的言情小说全集让读者略有兴趣。"},Aura={["ce711bb62d555139:43"]="催人泪下的言情小说全集让你略有兴趣。"}}
D.SpellTexts[243258]={Description={["855f5a8f8d015d22:53"]="催人泪下的言情小说全集让读者颇为感慨。"},Aura={["2119a2bfa6e04422:48"]="催人泪下的言情小说全集让你颇为感慨。"}}
D.SpellTexts[243259]={Description={["1f3338c997b78e50:49"]="催人泪下的言情小说全集让读者兴致盎然。"},Aura={["1030e8f9acdd7550:44"]="催人泪下的言情小说全集让你兴致盎然。"}}
D.SpellTexts[243261]={Description={["1735ac75be94a6ba:53"]="催人泪下的言情小说全集让读者无比亢奋。"},Aura={["b2eff4a5d8738dba:48"]="催人泪下的言情小说全集让你无比亢奋。"}}
D.SpellTexts[243265]={Description={["4c848ca06729d54d:76"]="召唤一个厄运石。如果有四名受害者完成末日仪式，其中的一个将会死亡。"}}
D.SpellTexts[243267]={Description={["9ef4bbd1a9f6efca:42"]="目标将不会受到熔火邪能的影响。"},Aura={["4ffba88d2cb5edb4:35"]="不会受到熔火邪能的影响。"}}
