D.SpellTexts[246301]={Description={["2813d18d754aeb70:116"]="施法者每隔一段时间向艾欧娜尔的精华发射邪能能量飞弹。\r\n在近战范围内与这个生物战斗会结束此效果。"},Aura={["df2a6062502cff0f:104"]="每隔一段时间向艾欧娜尔的精华发射邪能能量飞弹。\r\n在近战范围内与这个生物战斗会结束此效果。"}}
D.SpellTexts[246305]={Description={["f6b8ea5d3b7d9968:88"]="施法者向艾欧娜尔的精华发射一枚邪能能量飞弹，造成少量的火焰伤害。"}}
