D.SpellTexts[246421]={Description={["c66c3ff8e4a3b419:105"]="与阿古斯邪能之心建立连接，使你在受到致命伤害的时候能够免于死亡。 \r\n\r\n只能在阿古斯使用。\r\n\r\n"},Aura={["b9985b9f42a155ea:46"]="因与邪能之间的连接而免受致命伤害。"},Rank={["1044fc4216ed2ac5:5"]="等级 1"}}
