D.SpellTexts[249900]={Description={["6d60e570856cd745:79"]="目标已受到保护，免疫所有伤害。关闭所有强化控制台以移除此护盾。"},Aura={["7a8d3eb9f126fd5c:18"]="免疫所有伤害。"}}
D.SpellTexts[249934]={Description={["1c38bd23fbfd36fc:80"]="帕拉克希斯号发出一股席卷上层船体的邪能脉冲。船上的所有玩家都将死亡。"}}
