D.SpellTexts[250048]={Description={["4c0f109c86827a6f:126"]="艾欧娜尔汇聚自身的生命之力，对帕拉克希斯号造成自然伤害。此外，一道冲击波会横扫整个区域，对所有敌方入侵者造成伤害。"}}
D.SpellTexts[250073]={Description={["1fc6bf33a3aa13d0:111"]="该生物可以净化附近盟友身上所有的控制效果，并使其附近的盟友免疫控制效果。"},Aura={["b7a41fba5fe9ae71:48"]="移除附近盟友身上的控制效果。"}}
D.SpellTexts[250074]={Aura={["bf8cf778b0f7a301:33"]="免疫控制效果。"}}
D.SpellTexts[250081]={Description={["9818361875f2a65f:109"]="摧毁目标聚焦水晶。如果成功，施法者将按照水晶的颜色受到反馈效果的影响。"},Aura={["7e9c5e6c58bee385:11"]="粉碎。"}}
