D.SpellTexts[250342]={Description={["eeb49c266ba9699d:27"]="治疗附近的一个友方目标。"},Aura={["eeb49c266ba9699d:27"]="治疗附近的一个友方目标。"}}
D.SpellTexts[250373]={Description={["2d5692e7909dd774:48"]="召唤一头大主教的雷象。"}}
D.SpellTexts[250383]={Description={["b01f8c03e1d4829e:161"]="你的法术有几率唤醒圣光之心，在6秒内向8码内的敌人辐射500000点神圣伤害。\r\n\r\n圣光之心会为附近的盟友恢复生命，数值相当于其造成伤害的25%."},Aura={["b01f8c03e1d4829e:161"]="你的法术有几率唤醒圣光之心，在6秒内向8码内的敌人辐射500000点神圣伤害。\r\n\r\n圣光之心会为附近的盟友恢复生命，数值相当于其造成伤害的25%."}}
D.SpellTexts[250385]={Description={["2d5692e7909dd774:48"]="召唤一头大主教的雷象。"}}
D.SpellTexts[250386]={Description={["ca93142e05918b23:107"]="你的法术和技能有几率使你获得折射护盾，持续10秒，为你吸收最多35000点魔法伤害。"}}
D.SpellTexts[250389]={Description={["758cfd31b1b6190c:149"]="你的有害性法术和技能有几率造成1500点额外的神圣伤害。你的有益法术和技能有几率为离你最近的一名受伤的盟友恢复4500点生命。"}}
D.SpellTexts[250434]={Description={["39c5c6ed0d1d91b4:66"]="对目标位置的敌人造成神圣伤害并将其击退。"}}
D.SpellTexts[250437]={Aura={["8a20dabda654e132:20"]="正在骑乘战争机甲。"}}
D.SpellTexts[250474]={Description={["7abd1073ccf85102:15"]="处于静滞状态。"},Aura={["7abd1073ccf85102:15"]="处于静滞状态。"}}
D.SpellTexts[250492]={Description={["5ea19ed2c287a96b:69"]="使用矩阵上行链路，激活圣光裁决者，可以在阿古斯使用。"}}
D.SpellTexts[250531]={Description={["3b99a5f9b39fd234:63"]="从维迪卡尔上召唤光铸守护者来协助你战斗。"}}
D.SpellTexts[250554]={Description={["5273f6a5854259d0:56"]="帕拉克希斯号发出的冲击使所有防御护盾失去效果。"}}
D.SpellTexts[250631]={Aura={["89a7765164142a7e:21"]="被邪能魔法腐蚀。"}}
D.SpellTexts[250634]={Description={["479c1b23f6b1689e:132"]="你携带着一颗凝固的烈焰球。将它交给普洛克斯可为其充能。\r\n在携带烈焰期间，任何行动都会导致其掉落。"},Aura={["4ec84edbf885d9d4:69"]="把烈焰交给普洛克斯。\r\n任何行动都会使凝固的烈焰掉落。"}}
D.SpellTexts[250647]={Description={["af36500c783550c5:23"]="治愈目标的伤口。"}}
D.SpellTexts[250660]={Description={["52b9daa0ac35c3d1:64"]="用你的烈焰宝珠猛击附近的熏火裂隙，使其崩塌。"}}
D.SpellTexts[250676]={Aura={["dda2b69413e61af9:23"]="携带着烈焰之球。"}}
D.SpellTexts[250686]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[250734]={Description={["37803c33d665095e:54"]="用电离地理记录仪记录地貌。"}}
D.SpellTexts[250754]={Aura={["1b1334e5a8659048:27"]="死亡时会落下一颗烈焰宝珠。"}}
D.SpellTexts[250757]={Aura={["efc6a9dbb707d75a:38"]="苏拉雅正用宇宙之光瞄准你。"}}
D.SpellTexts[250772]={Description={["1ab179f231bfce69:32"]="你正拿着爆破弹药。"},Aura={["1ab179f231bfce69:32"]="你正拿着爆破弹药。"}}
D.SpellTexts[250779]={Description={["a1df7cdfcd84c1ca:67"]="使用时会让玩家会使用在维迪卡尔矩阵核心里选择的技能。"}}
D.SpellTexts[250796]={Description={["1bfe4140b6e284cd:43"]="将玩家传送到阿古斯的随机位置。"}}
D.SpellTexts[250801]={Description={["a4e07bf840c34b4d:54"]="对闪电之柱周围的敌人造成自然伤害。"},Aura={["9c31a7c1d64a9b6e:7"]="减速。"}}
D.SpellTexts[250823]={Description={["33c69738e34d9db9:53"]="对施法者面前锥形区域内的所有敌人造成火焰伤害。"}}
D.SpellTexts[250826]={Aura={["1ef1486fe7e86bd4:46"]="被虚空的癫狂呓语煽动，变得无比残暴。"}}
D.SpellTexts[250827]={Description={["7049d1cf68e2ede4:145"]="你可以在矩阵核心里选择阿古斯邪能之心。阿古斯邪能之心使你在受到致命伤害的时候能够复活。 \r\n\r\n只能在阿古斯使用。"},Aura={["47983d98f4ca43eb:67"]="通过与邪能之间的联结免受致命伤害。\r\n\r\n只能在阿古斯使用。"}}
D.SpellTexts[250829]={Description={["4cc5f2edaa061bdc:40"]="用虚空的力量煽动目标，使其变得残暴。"}}
D.SpellTexts[250830]={Aura={["47983d98f4ca43eb:67"]="通过与邪能之间的联结免受致命伤害。\r\n\r\n只能在阿古斯使用。"}}
D.SpellTexts[250831]={Description={["3a498ccbe86f296a:160"]="你可以在矩阵核心里选择维迪卡尔传送道标。维迪卡尔传送道标可以发送请求，将你传送到最近的光铸道标。 \r\n\r\n只能在阿古斯使用。 "},Aura={["47983d98f4ca43eb:67"]="通过与邪能之间的联结免受致命伤害。\r\n\r\n只能在阿古斯使用。"}}
D.SpellTexts[250832]={Description={["40a81ba8700b4029:202"]="你可以在矩阵核心里选择奥术回响遮罩。奥术回响遮罩让使用者可以在短时间内隐形，并在隐形结束时进入超能状态。 \r\n\r\n只能在阿古斯使用。 "}}
D.SpellTexts[250859]={Description={["2d5692e7909dd774:48"]="召唤一头大主教的雷象。"}}
D.SpellTexts[250903]={Description={["af588885b36b1f9a:94"]="将熔火邪能抛向高空，最终坠向地面，对附近敌人造成火焰伤害。"}}
D.SpellTexts[250917]={Description={["6ec2fca54a34a8b6:92"]="降落时，你可以向前推进一小段距离。\r\n\r\n快落地时，你的降落伞会自动打开。"},Aura={["6ec2fca54a34a8b6:92"]="降落时，你可以向前推进一小段距离。\r\n\r\n快落地时，你的降落伞会自动打开。"}}
D.SpellTexts[250926]={Aura={["25fa69ff26ec8c56:21"]="造成火焰伤害。"}}
D.SpellTexts[250929]={Description={["eccbbf2a1df95c5b:65"]="挥舞着炽燃之斧旋转，对附近所有敌人造成火焰伤害。"}}
D.SpellTexts[250941]={Description={["0f4ecbf2507492c7:72"]="猛扑向一名敌人，对冲击点附近的所有敌人造成物理伤害。"}}
D.SpellTexts[250947]={Description={["c9152ef3d262e388:60"]="吐出恶心的液体，对当前目标造成自然伤害。"}}
D.SpellTexts[250950]={Description={["35131ff576afe26a:49"]="施法者死亡时爆炸，造成自然伤害。"}}
D.SpellTexts[250962]={Description={["c886583fb1488a7a:95"]="跳向一名敌人，对冲击点附近的所有敌人造成物理伤害，并将他们击退。"}}
D.SpellTexts[251018]={Description={["c8e908a5f0e9030c:47"]="吐出一颗燃烧胆汁之球，造成火焰伤害。"}}
D.SpellTexts[251021]={Description={["4c5c35e6e468e729:95"]="发出震耳尖啸，造成物理伤害，并使施法者面前锥形范围内的所有敌人沉默。"},Aura={["9a2cd2fa3045010b:9"]="沉默。"}}
D.SpellTexts[251022]={Description={["7733ea777263a46e:58"]="横扫施法者前方锥形区域，造成两次火焰伤害。"}}
D.SpellTexts[251028]={Description={["887e9dc4c1b4bd6b:53"]="用黑暗能量冲击目标，造成暗影伤害。"}}
D.SpellTexts[251041]={Description={["4c72d5d98c1cf46a:41"]="将使用者传送到阿古斯上方的维迪卡尔。"}}
D.SpellTexts[251042]={Description={["e2113022df6a3867:50"]="向目标冲锋，在撞击时造成物理伤害。"}}
D.SpellTexts[251046]={Description={["7abd1073ccf85102:15"]="处于静滞状态。"},Aura={["7abd1073ccf85102:15"]="处于静滞状态。"}}
D.SpellTexts[251047]={Description={["c8be839f99a8476e:109"]="在目标脚下放置爆炸符文，几秒钟后爆炸，对附近所有敌人造成火焰伤害。"}}
D.SpellTexts[251073]={Aura={["f805960d6dea7856:25"]="不能攻击或施法。"}}
D.SpellTexts[251075]={Aura={["4778b0ef1cb2848e:109"]="艾娜拉释放她的全部力量，用神圣之力冲刷所有人，对敌人造成伤害，并为她的盟友恢复@251103s1点生命值。"}}
D.SpellTexts[251091]={Description={["c130ff681475868b:84"]="下令向施法者所在位置进行轰炸，每次击中时造成火焰伤害。"}}
D.SpellTexts[251094]={Description={["2c5ea34bef69ae04:99"]="大范围挥动手中的武器，对施法者面前锥形范围内的所有敌人造成物理伤害，并将他们击退。"}}
D.SpellTexts[251100]={Aura={["25fa69ff26ec8c56:21"]="造成火焰伤害。"}}
D.SpellTexts[251104]={Description={["282e30bca6c8e503:50"]="制造一件适用于你职业的T21灵魂绑定物品。"}}
D.SpellTexts[251105]={Description={["282e30bca6c8e503:50"]="制造一件适用于你职业的T21灵魂绑定物品。"}}
