D.SpellTexts[251112]={Description={["cc3f00b0f5951cf5:13"]="放置炸弹。"}}
D.SpellTexts[251123]={Description={["b4f7e793b1a99e34:118"]="冲击力使充能孢子嵌入你的皮肤，提高你的治疗和伤害技能的效果。"}}
D.SpellTexts[251125]={Aura={["62da1743786b99c6:23"]="造成奥术伤害。"}}
D.SpellTexts[251128]={Description={["2b551cc31d6ecad6:90"]="召唤一颗纯净的冰球飘离施法者，对其接触到的所有玩家造成冰霜伤害。"}}
D.SpellTexts[251133]={Description={["1fdd4cf357aea49a:86"]="向目标投掷强化后的盾牌，对目标及其周围的所有敌人造成神圣伤害。"}}
D.SpellTexts[251137]={Aura={["e59e6d1ffd03514e:56"]="使玩家获得俯冲回下方地面的能力。"}}
D.SpellTexts[251153]={Description={["ab6b1a4019cbbf39:75"]="这根坚硬的茎秆暴露在来自充能藤蔓的孢子下时会发生剧烈反应。"},Aura={["ab6b1a4019cbbf39:75"]="如果接触到带电藤蔓的孢子，僵化的茎秆就会产生剧烈反应。"}}
D.SpellTexts[251156]={Aura={["25fa69ff26ec8c56:21"]="造成火焰伤害。"}}
D.SpellTexts[251160]={Description={["9ac6a93f601571f8:63"]="用灌注邪能的剑攻击目标两次，造成火焰伤害"}}
D.SpellTexts[251161]={Description={["65797550ef45fcb7:75"]="抛出多把灌注邪能的飞刀，对附近所有敌人造成火焰伤害。"}}
D.SpellTexts[251162]={Description={["b5771066503865f5:41"]="将施法者传送到破碎群岛的达拉然。"}}
D.SpellTexts[251163]={Aura={["28718348f3d41ea5:23"]="造成自然伤害。"}}
D.SpellTexts[251165]={Description={["1751aa11575bf2a6:81"]="这根坚硬的茎秆可以用你头顶的巨型蘑菇上的充能藤蔓的孢子碾碎。"},Aura={["1751aa11575bf2a6:81"]="这根坚硬的茎秆可以用你头顶的巨型蘑菇上的充能藤蔓的孢子碾碎。"}}
D.SpellTexts[251166]={Description={["ed529a6addf1e2b7:80"]="当头猛击敌人，造成物理伤害，并将他们击退。"}}
D.SpellTexts[251170]={Aura={["c0b8756b7bf3a20e:46"]="对附近随机位置造成自然伤害。"}}
D.SpellTexts[251191]={Description={["4666fd95d63a2b8a:43"]="右键点击以召唤或解散你的幽灵鲨。"}}
D.SpellTexts[251203]={Aura={["25fa69ff26ec8c56:21"]="造成火焰伤害。"}}
D.SpellTexts[251206]={Description={["f5696ac3fa687678:40"]="召唤一个谄媚的小鬼协助施法者。"}}
D.SpellTexts[251217]={Aura={["979997f4ce4e183b:8"]="昏迷。"}}
D.SpellTexts[251218]={Aura={["77cae8760532a3d5:25"]="造成物理伤害。"}}
D.SpellTexts[251225]={Description={["e119931ff8924024:126"]="在附近敌人的位置召唤多枚不稳定的邪能水晶，并在几秒后爆炸，对附近所有敌人造成火焰伤害。"}}
D.SpellTexts[251246]={Description={["de34d7676e316e48:83"]="从高处向下冲撞，对冲击点附近的所有敌人造成物理伤害。"}}
D.SpellTexts[251247]={Description={["663d60eb201d7a3a:129"]="变形成一条鱼。你可以在水下呼吸，并以极快的速度游泳。\r\n\r\n在陆地上时你只能四处跳动，并且逐渐损失生命值。"}}
D.SpellTexts[251258]={Description={["20f45e2e3d045eb7:25"]="烹饪一顿百鱼宴。"}}
D.SpellTexts[251265]={Description={["fc14a835bc92ab54:100"]="施法者拍打翅膀，制造一阵邪能逆风，造成火焰伤害并将所有敌人推开。"},Aura={["55daeedb94bf485a:64"]="制造一阵邪能逆风，造成火焰伤害并将敌人推开。"}}
D.SpellTexts[251276]={Description={["7c3afe7af9118c03:74"]="施法者撞向地面，对一直线内的所有敌人造成物理伤害。"}}
D.SpellTexts[251281]={Aura={["25fa69ff26ec8c56:21"]="造成火焰伤害。"}}
D.SpellTexts[251283]={Description={["34ea6e829d8a97d3:62"]="强迫附近所有敌人向施法者移动。 "},Aura={["595d925b4469964a:25"]="吸引附近所有敌人。"}}
D.SpellTexts[251284]={Aura={["096219e7b8e2e098:8"]="被魅惑。"}}
D.SpellTexts[251291]={Description={["29f130f981d403fa:54"]="对另一个玩家使用，在他们的口袋里搜寻闪亮的东西。"}}
D.SpellTexts[251301]={Description={["9f2398df34d6ff86:29"]="你开始走迷宫。"},Aura={["f54f3129a6f6503c:16"]="走迷宫。"}}
D.SpellTexts[251302]={Description={["531268155ecc824e:104"]="发动大规模的圆弧斩，对施法者面前锥形范围内的所有敌人造成大量物理伤害，并将其击退。"}}
D.SpellTexts[251317]={Description={["eb0403ec975102bb:90"]="向各个方向释放压倒性的邪能能量，造成火焰伤害并降低移动速度。"},Aura={["68452f1c1ab13ef3:19"]="释放邪能能量。"}}
D.SpellTexts[251322]={Aura={["b7b35c3fc19a4a40:30"]="发动灌注邪能的狂怒攻击。"}}
